window.CC.p.push({n:3,view:"<section class=\"view\" id=\"p3\" hidden style=\"--c:#b7791f\"><h1><i>3</i>Internal Medicine</h1><p class=\"lead\">31 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 3A</h3><div class=\"card\" data-u=\"u20\"><button class=\"open\" data-u=\"u20\"><b>Overview</b><span>Internal Medicine &amp; Gastroenterology</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Internal+Medicine+%26+Gastroenterology+medical\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u21\"><button class=\"open\" data-u=\"u21\"><b>Case 1</b><span>Gastroesophageal Reflux Disease (GERD)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gastroesophageal+Reflux+Disease+%28GERD%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u22\"><button class=\"open\" data-u=\"u22\"><b>Case 2</b><span>Peptic Ulcer Disease (PUD) &amp; H. Pylori Gastritis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peptic+Ulcer+Disease+%28PUD%29+%26+H.+Pylori+Gastritis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u23\"><button class=\"open\" data-u=\"u23\"><b>Case 3</b><span>Acute Gastroenteritis (INFECTIOUS DIARRHEA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Gastroenteritis+%28INFECTIOUS+DIARRHEA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u24\"><button class=\"open\" data-u=\"u24\"><b>Case 4</b><span>Irritable Bowel Syndrome (IBS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Irritable+Bowel+Syndrome+%28IBS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u25\"><button class=\"open\" data-u=\"u25\"><b>Case 5</b><span>Cholelithiasis &amp; Acute Cholecystitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cholelithiasis+%26+Acute+Cholecystitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u26\"><button class=\"open\" data-u=\"u26\"><b>Case 6</b><span>Acute Pancreatitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pancreatitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u27\"><button class=\"open\" data-u=\"u27\"><b>Case 7</b><span>Acute Appendicitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Appendicitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u28\"><button class=\"open\" data-u=\"u28\"><b>Case 8</b><span>Upper Gastrointestinal Bleeding (UGIB)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Upper+Gastrointestinal+Bleeding+%28UGIB%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u29\"><button class=\"open\" data-u=\"u29\"><b>Case 9</b><span>Metabolic Dysfunction-Associated Steatotic Liver Disease (MASLD / NAFLD)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Metabolic+Dysfunction-Associated+Steatotic+Liver+Disease+%28MASLD+%2F+NAFLD%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u30\"><button class=\"open\" data-u=\"u30\"><b>Case 10</b><span>Viral Hepatitis (ACUTE HAV/HBV &amp; CHRONIC HBV/HCV IN EGYPT)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Viral+Hepatitis+%28ACUTE+HAV%2FHBV+%26+CHRONIC+HBV%2FHCV+IN+EGYPT%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u31\"><button class=\"open\" data-u=\"u31\"><b>Case 11</b><span>Liver Cirrhosis &amp; Portal Hypertension</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Liver+Cirrhosis+%26+Portal+Hypertension\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u32\"><button class=\"open\" data-u=\"u32\"><b>Case 12</b><span>Ascites &amp; Spontaneous Bacterial Peritonitis (SBP)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ascites+%26+Spontaneous+Bacterial+Peritonitis+%28SBP%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u33\"><button class=\"open\" data-u=\"u33\"><b>Case 13</b><span>Hepatic Encephalopathy (HE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hepatic+Encephalopathy+%28HE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u34\"><button class=\"open\" data-u=\"u34\"><b>Case 14</b><span>Inflammatory Bowel Disease (ULCERATIVE COLITIS &amp; CROHNʼS DISEASE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Inflammatory+Bowel+Disease+%28ULCERATIVE+COLITIS+%26+CROHN%CA%BCS+DISEASE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u35\"><button class=\"open\" data-u=\"u35\"><b>Case 15</b><span>Hemorrhoids, Anal Fissure &amp; Lower GI Bleeding Approach</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hemorrhoids%2C+Anal+Fissure+%26+Lower+GI+Bleeding+Approach\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 3B</h3><div class=\"card\" data-u=\"u36\"><button class=\"open\" data-u=\"u36\"><b>Case 16</b><span>Type 2 Diabetes Mellitus (T2DM) — Outpatient Management</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Type+2+Diabetes+Mellitus+%28T2DM%29+%E2%80%94+Outpatient+Management\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u37\"><button class=\"open\" data-u=\"u37\"><b>Case 17</b><span>Diabetic Ketoacidosis (DKA) &amp; Hyperosmolar Hyperglycemic State (HHS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Diabetic+Ketoacidosis+%28DKA%29+%26+Hyperosmolar+Hyperglycemic+State+%28HHS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u38\"><button class=\"open\" data-u=\"u38\"><b>Case 18</b><span>Hypoglycemia</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypoglycemia\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u39\"><button class=\"open\" data-u=\"u39\"><b>Case 19</b><span>Hypothyroidism</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypothyroidism\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u40\"><button class=\"open\" data-u=\"u40\"><b>Case 20</b><span>Hyperthyroidism (THYROTOXICOSIS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hyperthyroidism+%28THYROTOXICOSIS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u41\"><button class=\"open\" data-u=\"u41\"><b>Case 21</b><span>Iron Deficiency Anemia (IDA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Iron+Deficiency+Anemia+%28IDA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u42\"><button class=\"open\" data-u=\"u42\"><b>Case 22</b><span>Vitamin B12 Deficiency &amp; Megaloblastic Anemia</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vitamin+B12+Deficiency+%26+Megaloblastic+Anemia\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u43\"><button class=\"open\" data-u=\"u43\"><b>Case 23</b><span>Urinary Tract Infection (CYSTITIS &amp; ACUTE PYELONEPHRITIS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urinary+Tract+Infection+%28CYSTITIS+%26+ACUTE+PYELONEPHRITIS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u44\"><button class=\"open\" data-u=\"u44\"><b>Case 24</b><span>Acute Kidney Injury (AKI)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Kidney+Injury+%28AKI%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u45\"><button class=\"open\" data-u=\"u45\"><b>Case 25</b><span>Chronic Kidney Disease (CKD)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Kidney+Disease+%28CKD%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u46\"><button class=\"open\" data-u=\"u46\"><b>Case 26</b><span>Nephrolithiasis (RENAL &amp; URETERIC STONES)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nephrolithiasis+%28RENAL+%26+URETERIC+STONES%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u47\"><button class=\"open\" data-u=\"u47\"><b>Case 27</b><span>Gout &amp; Hyperuricemia</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gout+%26+Hyperuricemia\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u48\"><button class=\"open\" data-u=\"u48\"><b>Case 28</b><span>Rheumatoid Arthritis (RA) &amp; Osteoarthritis (OA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Rheumatoid+Arthritis+%28RA%29+%26+Osteoarthritis+%28OA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u49\"><button class=\"open\" data-u=\"u49\"><b>Case 29</b><span>Enteric (TYPHOID) Fever &amp; Brucellosis (EGYPTIAN FEBRILE CLASSICS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Enteric+%28TYPHOID%29+Fever+%26+Brucellosis+%28EGYPTIAN+FEBRILE+CLASSICS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u50\"><button class=\"open\" data-u=\"u50\"><b>Case 30</b><span>Deep Vein Thrombosis (DVT) &amp; Critical Electrolyte Emergencies</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Deep+Vein+Thrombosis+%28DVT%29+%26+Critical+Electrolyte+Emergencies\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u20\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Overview</span><h1>Internal Medicine &amp; Gastroenterology</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Internal+Medicine+%26+Gastroenterology+medical\">🔍 Search on Google</a></header><h4><i><b>Top Daily Clinical Cases in Egyptian Practice</b></i></h4><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u21\">Case 1 →</button></nav></article><article class=\"view unit\" id=\"u21\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Gastroesophageal Reflux Disease (GERD)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gastroesophageal+Reflux+Disease+%28GERD%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><mark class=\"hl lab\"><b>GERD</b></mark> (Gastroesophageal Reflux Disease) is a chronic condition in which retrograde flow (reflux) of gastric contents into the esophagus causes troublesome symptoms and/or mucosal injury (esophagitis).</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Mechanical / Anatomical Causes:</b></span></p>\n<ul>\n<li class=\"l2\">Transient <mark class=\"hl dx\"><b>LES</b></mark> (Lower Esophageal Sphincter) relaxations (most common mechanism).</li>\n<li class=\"l2\">Decreased resting <mark class=\"hl dx\"><b>LES</b></mark> tone.</li>\n<li class=\"l2\"><b>Hiatal Hernia</b> (sliding type disrupts the diaphragmatic pinch around the LES).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Increased Intra-Abdominal Pressure:</b></span></p>\n<ul>\n<li class=\"l2\">Central obesity.</li>\n<li class=\"l2\">Pregnancy.</li>\n<li class=\"l2\">Ascites or tight clothing around the waist.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Impaired Esophageal Clearance / Gastric Emptying:</b></span></p>\n<ul>\n<li class=\"l2\">Gastroparesis (e.g., diabetic autonomic neuropathy).</li>\n<li class=\"l2\">Decreased salivary bicarbonate secretion (e.g., Sjögren’s syndrome, smoking).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Dietary &amp; Pharmacological Triggers:</b></span></p>\n<ul>\n<li class=\"l2\">Dietary: Fatty meals, chocolate, caffeine, peppermint, spicy/acidic foods, heavy late-night meals.</li>\n<li class=\"l2\">Medications: <b>CCBs</b> (Calcium Channel Blockers), nitrates, anticholinergics, <mark class=\"hl rx\"><b>NSAIDs</b></mark> (Non-Steroidal Anti-Inflammatory Drugs), bisphosphonates.</li>\n</ul><h3><b>3. Pathophysiology</b></h3><p>Failure of the anti-reflux barrier (LES + crural diaphragm) allows gastric acid, pepsin, and bile to contact esophageal squamous mucosa, triggering mucosal inflammation, erosions, and potential metaplasia.</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Typical Symptoms:</b> Heartburn (retrosternal burning pain radiating upward, worse after meals or when lying flat/bending over) and acid regurgitation (sour/bitter taste in mouth).</li>\n<li class=\"l1\"><b>Atypical (Extra-esophageal) Symptoms:</b> Chronic cough, nocturnal asthma exacerbations, hoarseness (reflux laryngitis), dental erosions, non-cardiac chest pain.</li>\n<li class=\"l1\"><b>Red Flags (ALARM):</b> Dysphagia, odynophagia, GI bleeding, unexplained weight loss, anemia, onset &gt; 50–55 years.</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Clinical Diagnosis:</b> Typical symptoms without alarm features justify an empirical <mark class=\"hl rx\"><b>PPI</b></mark> (Proton Pump Inhibitor) trial.</li>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Upper GI Endoscopy — EGD</b></mark> (Esophagogastroduodenoscopy): <mark class=\"hl mech\"><b>Gold standard</b></mark> for mucosal evaluation (Los Angeles classification Grades A–D) and biopsy (indicated if alarm symptoms exist or symptoms fail 8 weeks of PPI therapy).</li>\n<li class=\"l1\"><b>24-Hour Ambulatory pH / Impedance Monitoring:</b> Best test to confirm acid/non-acid reflux when EGD is normal (<b>NERD</b> — Non-Erosive Reflux Disease).</li>\n<li class=\"l1\"><b>Esophageal Manometry:</b> Performed prior to anti-reflux surgery to exclude motility disorders (e.g., achalasia).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>ACS</b></mark> (Acute Coronary Syndrome) / Angina (always rule out cardiac ischemia first in atypical chest pain!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>PUD</b></mark> (Peptic Ulcer Disease) / Gastritis.</li>\n<li class=\"l1\">Esophageal motility disorders (Achalasia, Esophageal Spasm).</li>\n<li class=\"l1\">Eosinophilic Esophagitis &amp; Pill-induced Esophagitis.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\">Erosive esophagitis and esophageal ulceration.</li>\n<li class=\"l1\">Peptic esophageal stricture (progressive solid-food dysphagia).</li>\n<li class=\"l1\"><b>Barrett’s Esophagus</b> (intestinal metaplasia: squamous epithelium replaced by columnar goblet cells — premalignant for <b>Esophageal Adenocarcinoma</b>).</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Lifestyle Modifications:</b> Weight reduction, elevate head of bed 15–20 cm, avoid eating within 3 hours of bedtime, avoid trigger foods, smoking cessation.</li>\n<li class=\"l1\"><b>Pharmacotherapy:</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>PPIs</b></mark> (First-line): Omeprazole 20–40 mg, Esomeprazole 20–40 mg, or Pantoprazole 40 mg <b>30–60 minutes before breakfast</b> for 4–8 weeks.</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>H2RAs</b></mark> (Histamine-2 Receptor Antagonists): Famotidine 20–40 mg at bedtime (useful for nocturnal acid breakthrough).</li>\n<li class=\"l2\"><b>Antacids / Alginates</b> (e.g., Gaviscon): Rapid, short-term symptomatic relief.</li>\n<li class=\"l1\"><b>Surgical / Endoscopic:</b> Laparoscopic <mark class=\"hl rx\"><b>Nissen Fundoplication</b></mark> (for refractory GERD or large symptomatic hiatal hernia).</li>\n</ul>\n<p><b>Clinical Pearl:</b> <i>Always take a PPI 30–60 minutes BEFORE the first meal of the day so active proton pumps are maximally inhibited when food stimulates acid secretion.</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u20\">← Overview</button><button class=\"nv\" data-u=\"u22\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u22\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Peptic Ulcer Disease (PUD) &amp; H. Pylori Gastritis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peptic+Ulcer+Disease+%28PUD%29+%26+H.+Pylori+Gastritis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><mark class=\"hl lab\"><b>PUD</b></mark> (Peptic Ulcer Disease) is a mucosal defect ≥ 5 mm extending through the muscularis mucosae of the stomach (<b>Gastric Ulcer</b>) or proximal duodenum (<b>Duodenal Ulcer</b>).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i><b>Helicobacter pylori</b></i><b> Infection:</b> Accounts for ~80–90% of duodenal ulcers and ~70% of gastric ulcers (hyperendemic in Egypt).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Medications:</b> Chronic <mark class=\"hl rx\"><b>NSAIDs</b></mark> (Non-Steroidal Anti-Inflammatory Drugs) and Aspirin use (inhibit <mark class=\"hl dx\"><b>COX-1</b></mark> [Cyclooxygenase-1] mediated protective prostaglandins); corticosteroids (especially when combined with NSAIDs).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Physiologic Stress:</b> Severe burns (<b>Curling’s ulcer</b>), head trauma/raised <b>ICP</b> (<b>Cushing’s ulcer</b>), <b>ICU</b> (Intensive Care Unit) sepsis/mechanical ventilation.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Hypersecretory States:</b> <b>ZES</b> (Zollinger-Ellison Syndrome — gastrin-secreting tumor / gastrinoma).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Lifestyle Cofactors:</b> Smoking (impairs mucosal healing), alcohol.</span></p><h3><b>3. Pathophysiology</b></h3><p>Imbalance between <b>aggressive factors</b> (gastric acid, pepsin) and <b>defensive factors</b> (mucus-bicarbonate barrier, prostaglandins, mucosal blood flow). <i>H. pylori </i>produces <b>urease</b> (creating an alkaline ammonia cloud) and triggers chronic antral inflammation, increasing gastrin and acid secretion.</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Duodenal Ulcer:</b> Epigastric gnawing/burning pain occurring 2–5 hours after meals and often <b>waking the patient at night</b>; characteristically <b>relieved by food or antacids</b>.</li>\n<li class=\"l1\"><b>Gastric Ulcer:</b> Epigastric pain <b>worsened by food</b>, accompanied by nausea, early satiety, and weight loss.</li>\n<li class=\"l1\"><b>Exam:</b> Mild epigastric tenderness (severe rigidity suggests perforation).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Non-invasive </b><i><b>H. pylori</b></i><b> Tests</b> (if patient &lt; 50–55 years with NO alarm symptoms):</li>\n<li class=\"l2\"><b>Stool Antigen Test</b> (active infection — preferred in Egypt alongside Urea Breath Test).</li>\n<li class=\"l2\"><b>Urea Breath Test</b> (<mark class=\"hl mech\"><b> UBT</b></mark> — active infection; high sensitivity/specificity).</li>\n<li class=\"l2\"><i>Critical Note:</i> Stop <mark class=\"hl rx\"><b>PPIs for 2 weeks</b></mark> and <b>antibiotics/bismuth for 4 weeks</b> before UBT or Stool Antigen to avoid false-negative results! (<i>Serum IgG serology cannot distinguish active from past infection</i>.)</li>\n<li class=\"l1\"><mark class=\"hl rx\"><b>EGD</b></mark> (Esophagogastroduodenoscopy) + Biopsy: <mark class=\"hl mech\"><b>Gold standard</b></mark> (mandatory in alarm symptoms, age &gt; 50–55, or gastric ulcers to rule out <b>Gastric Adenocarcinoma</b>; repeat EGD after 8–12 weeks for gastric ulcers to confirm healing).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">GERD, Non-ulcer (functional) dyspepsia, Biliary colic / Cholecystitis, Acute Pancreatitis, Gastric malignancy, Inferior wall <mark class=\"hl lab\"><b>MI</b></mark> (Myocardial Infarction).</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><b>Upper GI Bleeding</b> (most common complication — hematemesis/melena).</li>\n<li class=\"l1\"><b>Perforation</b> (sudden severe generalized pain, rigid abdomen, free air under diaphragm on erect <mark class=\"hl mech\"><b>CXR</b></mark> [Chest X-Ray]).</li>\n<li class=\"l1\"><b>Gastric Outlet Obstruction</b> (persistent postprandial vomiting, succussion splash).</li>\n<li class=\"l1\"><b>Penetration</b> (into pancreas -&gt; severe back pain + elevated amylase).</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Stop Offending Agents:</b> Discontinue NSAIDs, smoking, alcohol.</li>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Eradication of </b></mark><i><b>H. pylori</b></i><mark class=\"hl rx\"><b> (14-Day Regimens — Bismuth Quadruple Therapy preferred due to high Clarithromycin resistance in Egypt):</b></mark></li>\n<li class=\"l2\"><b>Bismuth Quadruple Therapy (14 days):</b> <mark class=\"hl rx\"><b>PPI</b></mark> twice daily + Bismuth subsalicylate/subcitrate <b>QID</b> (4 times daily) + Tetracycline 500 mg QID + Metronidazole 500 mg <b>TID</b> (3 times daily).</li>\n<li class=\"l2\"><b>Concomitant Non-Bismuth Quadruple Therapy (14 days):</b> <mark class=\"hl rx\"><b>PPI</b></mark> BID + Amoxicillin 1 g BID + Clarithromycin 500 mg BID + Metronidazole 500 mg BID.</li>\n<li class=\"l2\"><i>Test of Cure:</i> Perform UBT or Stool Antigen at least <b>4 weeks after finishing antibiotics</b> (and 2 weeks off PPI).</li>\n<li class=\"l1\"><b>NSAID-Induced Ulcer:</b> Stop NSAID + PPI for 8 weeks (if NSAID cannot be stopped, co-prescribe PPI or switch to selective <mark class=\"hl dx\"><b>COX-2</b></mark> inhibitor).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u21\">← Case 1</button><button class=\"nv\" data-u=\"u23\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u23\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Acute Gastroenteritis (INFECTIOUS DIARRHEA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Gastroenteritis+%28INFECTIOUS+DIARRHEA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Acute inflammation of the stomach and intestinal tract resulting in ≥ 3 loose/watery stools per day lasting <b>&lt; 14 days</b> (Persistent: 14–29 days; Chronic: ≥ 30 days).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Viral Causes (Most Common Overall — Watery Diarrhea):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Norovirus</i> (common in adults/outbreaks), <i>Rotavirus</i> (children), <i>Adenovirus</i>.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Bacterial Causes (Separated by Mechanism):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Preformed Toxin (Rapid onset 1–6 hrs):</i> <i>Staphylococcus aureus</i>, <i>Bacillus cereus</i>.</li>\n<li class=\"l2\"><i>Enterotoxin (Watery):</i> <b>ETEC</b> (Enterotoxigenic <i>Escherichia coli</i> — Traveler’s diarrhea), <i>Vibrio cholerae</i> (\"rice-water\" stool).</li>\n<li class=\"l2\"><i>Invasive / Cytotoxic (Inflammatory / Dysentery):</i> <i>Shigella</i>, <i>Salmonella</i>, <i>Campylobacter jejuni</i>, <b>EHEC</b> (Enterohemorrhagic <i>E. coli</i> O157:H7), <i>Clostridioides difficile </i>(post-antibiotics).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Parasitic Causes (Very Common in Egypt):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Entamoeba histolytica</i> (amebic dysentery), <i>Giardia lamblia</i> (foul-smelling greasy stools, bloating), <i>Cryptosporidium</i>.</li>\n</ul><h3><b>3. Pathophysiology</b></h3><p>Either <b>secretory</b> (toxins activate <b>cAMP/cGMP</b> causing massive chloride/water loss without mucosal destruction) or <b>inflammatory/invasive</b> (mucosal invasion causing ulceration, blood, pus, and fever).</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Non-inflammatory (Watery):</b> Profuse watery diarrhea, nausea, vomiting, periumbilical cramps, minimal/no fever.</li>\n<li class=\"l1\"><b>Inflammatory (Dysentery):</b> Small-volume bloody/mucoid stools, fever, tenesmus, <b>LLQ</b> (Left Lower Quadrant) cramping.</li>\n<li class=\"l1\"><b>Assess Hydration Status:</b> Thirst, dry mucous membranes, tachycardia, postural hypotension, oliguria, sunken eyes, poor skin turgor.</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\">Most uncomplicated mild cases require <b>NO labs</b>.</li>\n<li class=\"l1\"><b>Indications for Workup</b> (severe dehydration, fever ≥ 38.5°C, bloody stools, duration &gt; 7 days, immunocompromised):</li>\n<li class=\"l2\"><b>Stool Analysis</b> (leukocytes, <b>RBCs</b> [Red Blood Cells], ova/parasites, trophozoites).</li>\n<li class=\"l2\"><b>Stool Culture</b> +/- <i>C. difficile</i> toxin assay (if recent antibiotic exposure).</li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>Serum Electrolytes &amp; RFTs</b></mark> (Renal Function Tests: Urea, Creatinine) in moderate-to-severe dehydration.</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Acute appendicitis, <mark class=\"hl lab\"><b>IBD</b></mark> (Inflammatory Bowel Disease) flare, Ischemic colitis, Drug-induced diarrhea (Metformin, Magnesium, antibiotics), Overflow diarrhea from fecal impaction.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\">Hypovolemic shock, <mark class=\"hl lab\"><b>AKI</b></mark> (Acute Kidney Injury — pre-renal), Electrolyte imbalances (hypokalemia, hyponatremia, metabolic acidosis), <b>HUS</b> (Hemolytic Uremic Syndrome with EHEC), <mark class=\"hl lab\"><b>GBS</b></mark> (Guillain-Barré Syndrome post-<i>Campylobacter</i>), Amebic liver abscess.</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Cornerstone = Rehydration:</b></li>\n<li class=\"l2\">Mild-Moderate: <b>ORS</b> (Oral Rehydration Solution — WHO low-osmolarity formula).</li>\n<li class=\"l2\">Severe / Persistent vomiting / Shock: IV <b>Ringer’s Lactate</b> or <b>0.9% Normal Saline</b> + Potassium supplementation once urine output is established.</li>\n<li class=\"l1\"><b>Diet:</b> Continue early feeding (BRAT-style/bland diet); avoid dairy temporarily if secondary lactase deficiency occurs, avoid sugary sodas.</li>\n<li class=\"l1\"><b>Symptomatic:</b> <b>Loperamide</b> ONLY in non-bloody, afebrile watery diarrhea (CONTRAINDICATED in bloody diarrhea/high fever — risk of toxic megacolon!). Antiemetics (Ondansetron).</li>\n<li class=\"l1\"><b>Antibiotics (Avoid in routine viral/mild cases! Indicated in severe bacterial dysentery, sepsis, immunocompromised, or specific parasites):</b></li>\n<li class=\"l2\"><i>Empirical Bacterial Dysentery:</i> Azithromycin 500 mg OD for 3 days (or Ciprofloxacin 500 mg BID for 3–5 days — avoid fluoroquinolones if <i>Campylobacter </i>resistance suspected or in children/pregnancy).</li>\n<li class=\"l2\"><i>Amebiasis / Giardiasis:</i> Metronidazole 500–750 mg TID for 7–10 days (plus luminal agent e.g. Paromomycin/Diloxanide for <i>E. histolytica</i> cysts).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u22\">← Case 2</button><button class=\"nv\" data-u=\"u24\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u24\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Irritable Bowel Syndrome (IBS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Irritable+Bowel+Syndrome+%28IBS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><mark class=\"hl lab\"><b>IBS</b></mark> (Irritable Bowel Syndrome) is a chronic functional disorder of <b>gut-brain interaction</b> characterized by recurrent abdominal pain associated with altered bowel habits in the absence of structural/biochemical pathology.</p><h3><b>2. Etiology &amp; Contributing Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Visceral Hypersensitivity:</b> Lowered pain threshold to normal gut distension.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Altered Gut Motility:</b> Accelerated (diarrhea) or delayed (constipation) transit.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Post-Infectious Gut Dysbiosis:</b> Follows acute bacterial/parasitic gastroenteritis (~10% of cases).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Psychosocial Factors:</b> Stress, anxiety, depression altering the brain-gut axis.</span></p><h3><b>3. Clinical Picture (Rome IV Criteria)</b></h3><ul>\n<li class=\"l1\">Recurrent abdominal pain ≥ 1 day/week in the last 3 months (symptom onset ≥ 6 months prior), associated with <b>≥ 2 of the following:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Related to defecation (relieved or worsened).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Associated with a change in stool frequency.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\">Associated with a change in stool form/appearance.</span></p>\n<ul>\n<li class=\"l1\"><b>Subtypes:</b> <mark class=\"hl lab\"><b>IBS-D</b></mark> (Diarrhea-predominant), <mark class=\"hl lab\"><b>IBS-C</b></mark> (Constipation-predominant), <mark class=\"hl lab\"><b>IBS-M</b></mark> (Mixed), <mark class=\"hl lab\"><b>IBS-U</b></mark> (Unclassified).</li>\n<li class=\"l1\"><b>Crucial Check:</b> Must have <b>NO Red Flags</b> (no nocturnal diarrhea waking patient from sleep, no weight loss, no rectal bleeding, no anemia, no fever, no onset &gt; 50 years).</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis of Exclusion with Minimal Testing</b> if typical Rome IV symptoms and NO red flags:</li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>CBC</b></mark> (Complete Blood Count) + <mark class=\"hl mech\"><b>CRP</b></mark> (C-Reactive Protein) or Fecal Calprotectin (to rule out <mark class=\"hl lab\"><b>IBD</b></mark> ).</li>\n<li class=\"l2\"><b>Stool Analysis</b> (especially in Egypt to exclude <i>Giardia</i> or <i>Entamoeba</i>).</li>\n<li class=\"l2\"><b>Celiac Serology</b> (Anti-tTG [Tissue Transglutaminase] IgA + total IgA) in IBS-D/IBS-M.</li>\n<li class=\"l1\"><b>Colonoscopy:</b> Indicated ONLY if alarm features are present or patient is ≥ 45–50 years due for screening.</li>\n</ul><h3><b>5. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">IBD (Ulcerative Colitis / Crohn’s), Celiac disease, Chronic parasitic infection (Giardiasis), Microscopic colitis, Colorectal cancer (&gt; 50 years), Hypo/Hyperthyroidism, Endometriosis.</li>\n</ul><h3><b>6. Complications</b></h3><ul>\n<li class=\"l1\">No risk of malignancy or mortality, but causes severe <b>impaired quality of life</b>, anxiety, and unnecessary surgeries if misdiagnosed.</li>\n</ul><h3><b>7. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Reassurance &amp; Education:</b> Explain benign chronic nature and gut-brain connection.</li>\n<li class=\"l1\"><b>Dietary:</b> Low-<b>FODMAP</b> (Fermentable Oligosaccharides, Disaccharides, Monosaccharides, and Polyols) diet trial; soluble fiber (Psyllium/Ispaghula) for IBS-C.</li>\n<li class=\"l1\"><b>Targeted Pharmacotherapy:</b></li>\n<li class=\"l2\"><i>Abdominal Pain/Spasm:</i> Antispasmodics (Mebeverine 135–200 mg, Hyoscine butylbromide, or Peppermint oil).</li>\n<li class=\"l2\"><i>IBS-D:</i> Loperamide, Rifaximin (non-absorbable antibiotic for bloating/diarrhea), low-dose <b>TCAs</b> (Tricyclic Antidepressants — e.g., Amitriptyline 10–25 mg at night for visceral pain + slowing transit).</li>\n<li class=\"l2\"><i>IBS-C:</i> Polyethylene glycol (<b>PEG</b>), Lactulose/Macrogol, Linaclotide/Lubiprostone.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u23\">← Case 3</button><button class=\"nv\" data-u=\"u25\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u25\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Cholelithiasis &amp; Acute Cholecystitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cholelithiasis+%26+Acute+Cholecystitis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Cholelithiasis:</b></mark> Presence of stones in the gallbladder (biliary colic if transient cystic duct obstruction).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Acute Cholecystitis:</b></mark> Acute inflammation of the gallbladder wall, usually due to persistent cystic duct obstruction by a gallstone (90–95%).</li>\n</ul><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Cholesterol Stones (~80% — \"5 Fs\"):</b> <b>F</b>emale, <b>F</b>orty, <b>F</b>ertile, <b>F</b>at (obesity), <b>F</b>amily history + rapid weight loss, <b>OCPs</b> (Oral Contraceptive Pills).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Pigment Stones (~20%):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Black stones:</i> Chronic hemolysis (e.g., Thalassemia, Sickle cell disease — common in Egypt), cirrhosis.</li>\n<li class=\"l2\"><i>Brown stones:</i> Biliary tract infection + stasis.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Acalculous Cholecystitis (5–10%):</b> Occurs in critically ill <b>ICU</b> patients, severe trauma, burns, sepsis, or prolonged <b>TPN</b> (Total Parenteral Nutrition) due to gallbladder ischemia and stasis.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Biliary Colic:</b> Episodic <b>RUQ</b> (Right Upper Quadrant) or epigastric pain lasting 30 min–6 hrs, triggered by fatty meals, radiating to <b>right scapula/shoulder</b>, NO fever, normal <mark class=\"hl mech\"><b>WBC</b></mark> .</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Acute Cholecystitis:</b></mark> Constant severe RUQ pain <b>&gt; 6 hours</b>, fever, nausea/vomiting, anorexia.</li>\n<li class=\"l1\"><b>Classic Exam Sign — Murphy’s Sign:</b> Inspiratory arrest during deep palpation of the RUQ under the right costal margin.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Abdominal Ultrasound (First-line / Gold Standard):</b> Gallstones, gallbladder wall thickening (&gt; 3–4 mm), pericholecystic fluid, <b>sonographic Murphy’s sign</b>.</li>\n<li class=\"l1\"><b>Labs:</b> Leukocytosis, mild elevation of bilirubin/ALP (if marked bilirubin/ALP elevation -&gt; suspect <b>Choledocholithiasis</b> [CBD stone]!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>HIDA Scan</b></mark> (Hepatobiliary Iminodiacetic Acid): Most sensitive/specific if ultrasound is equivocal (non-visualization of gallbladder).</li>\n</ul><h3><b>5. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Acute Pancreatitis, Peptic Ulcer perforation, Acute Hepatitis, Ascending Cholangitis, Right lower lobe Pneumonia, Inferior MI, Renal colic.</li>\n</ul><h3><b>6. Complications</b></h3><ul>\n<li class=\"l1\">Gallbladder empyema, gangrene, perforation (biliary peritonitis), <b>Mirizzi’s Syndrome</b> (stone compressing common hepatic duct), Gallstone ileus (fistula to duodenum).</li>\n</ul><h3><b>7. Treatment</b></h3><ul>\n<li class=\"l1\"><b>NPO</b> (Nothing by Mouth), IV hydration, IV analgesia (NSAIDs e.g., Ketorolac, or Opioids), Antiemetics.</li>\n<li class=\"l1\"><b>IV Antibiotics</b> (covering Gram-negatives &amp; anaerobes): Ceftriaxone + Metronidazole (or Piperacillin-Tazobactam in severe cases).</li>\n<li class=\"l1\"><b>Definitive Treatment:</b> Early <mark class=\"hl rx\"><b>Laparoscopic Cholecystectomy</b></mark> (ideally within 24–72 hours of admission).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u24\">← Case 4</button><button class=\"nv\" data-u=\"u26\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u26\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Acute Pancreatitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pancreatitis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Acute inflammation of the pancreas caused by premature intracellular activation of pancreatic digestive enzymes (autodigestion).</p><h3><b>2. Etiology (Separated — Mnemonic: \"I GET SMASHED\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Obstructive Causes (Most Common in Egypt):</b></span></p>\n<ul>\n<li class=\"l2\"><b>G</b>allstones (migration blocking ampulla of Vater — #1 overall in females/Egypt).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Toxic / Metabolic Causes:</b></span></p>\n<ul>\n<li class=\"l2\"><b>E</b>thanol (alcohol — #1 in Western males), <b>H</b>ypertriglyceridemia (&gt; 1,000 mg/dL), <b>H</b>ypercalcemia.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Iatrogenic / Procedural:</b></span></p>\n<ul>\n<li class=\"l2\">Post-<mark class=\"hl rx\"><b> ERCP</b></mark> (Endoscopic Retrograde Cholangiopancreatography).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Traumatic / Vascular:</b></span></p>\n<ul>\n<li class=\"l2\">Blunt abdominal <b>T</b>rauma (bicycle handlebar in kids), ischemia.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Drugs / Infections / Autoimmune:</b></span></p>\n<ul>\n<li class=\"l2\"><b>D</b>rugs (Azathioprine, Valproate, Thiazides, Furosemide, <mark class=\"hl rx\"><b>GLP-1</b></mark> agonists, Sulfonamides).</li>\n<li class=\"l2\"><b>M</b>umps, Coxsackievirus, <b>S</b>corpion sting (classic!), <b>I</b>diopathic.</li>\n</ul><h3><b>3. Diagnosis (Requires ≥ 2 of 3 Atlanta Criteria)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Characteristic acute epigastric pain radiating straight to the <mark class=\"hl dx\"><b>back</b></mark> (relieved by leaning forward).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Serum <b>Lipase</b> (preferred — more specific and stays elevated longer) or <b>Amylase</b> <b>≥ 3× Upper Limit of Normal</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\">Characteristic findings on <b>CT</b> / <mark class=\"hl mech\"><b>MRI</b></mark> / Ultrasound.</span></p><h3><b>4. Clinical Picture &amp; Exam</b></h3><ul>\n<li class=\"l1\">Severe epigastric pain radiating to back, persistent nausea/vomiting, tachycardia, hypotension, fever.</li>\n<li class=\"l1\"><b>Cullen’s Sign</b> (periumbilical ecchymosis) &amp; <b>Grey Turner’s Sign</b> (flank ecchymosis) -&gt; indicate retroperitoneal hemorrhage (necrotizing pancreatitis).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> Serum Lipase, Amylase, <mark class=\"hl mech\"><b>CBC</b></mark> , <b>CMP</b> (Comprehensive Metabolic Panel: Calcium, LFTs, Creatinine), Triglycerides, <mark class=\"hl mech\"><b>ABG</b></mark> (Arterial Blood Gas), <mark class=\"hl mech\"><b>LDH</b></mark> (Lactate Dehydrogenase).</li>\n<li class=\"l1\"><b>Abdominal Ultrasound:</b> Done on admission in ALL patients to look for gallstones!</li>\n<li class=\"l1\"><b>Contrast-Enhanced CT Abdomen:</b> NOT needed immediately if diagnosis is clear; performed after <b>48–72 hours</b> in severe/non-improving cases to assess pancreatic necrosis.</li>\n<li class=\"l1\"><b>Severity Scoring:</b> <b>BISAP Score</b> or <b>Ranson’s Criteria</b>.</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Perforated peptic ulcer, Acute cholecystitis/cholangitis, Mesenteric ischemia, Ruptured <mark class=\"hl lab\"><b>AAA</b></mark> (Abdominal Aortic Aneurysm), Inferior <mark class=\"hl lab\"><b>STEMI</b></mark> .</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><b>Early/Systemic:</b> Hypovolemic shock, <mark class=\"hl lab\"><b>ARDS</b></mark> (Acute Respiratory Distress Syndrome), <mark class=\"hl lab\"><b>AKI</b></mark> , Hypocalcemia (fat saponification).</li>\n<li class=\"l1\"><b>Local:</b> Pancreatic pseudocyst (&gt; 4 weeks), Walled-off necrosis, Infected pancreatic necrosis, Splenic vein thrombosis.</li>\n</ul><h3><b>8. Treatment (Supportive Triad)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Aggressive Early IV Fluid Resuscitation:</b> <b>Ringer’s Lactate</b> (preferred over Normal Saline to reduce acidosis/SIRS) — moderate goal-directed rate (avoid fluid overload!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Pain Control:</b> IV opioids (e.g., Fentanyl or Morphine) or IV Acetaminophen.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Bowel Rest &amp; Early Enteral Nutrition:</b> <b>NPO</b> initially until pain/nausea improve, then start early oral/enteral feeding within 24–72 hrs (prevents gut bacterial translocation!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Treat Cause:</b> Urgent <mark class=\"hl rx\"><b>ERCP</b></mark> within 24 hrs ONLY if concurrent <b>acute cholangitis</b> or persistent biliary obstruction; Cholecystectomy during same admission once resolved for gallstone pancreatitis. <i>Do NOT give prophylactic antibiotics unless infected necrosis is proven!</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u25\">← Case 5</button><button class=\"nv\" data-u=\"u27\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u27\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Acute Appendicitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Appendicitis\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Acute inflammation of the vermiform appendix, representing the most common surgical abdominal emergency worldwide.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Luminal Obstruction in Children/Adolescents:</b> Lymphoid hyperplasia (often post-viral infection).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Luminal Obstruction in Adults:</b> Fecalith (appendicolith — calcified stool).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Rare Causes:</b> Parasites (<i>Enterobius vermicularis</i>, <i>Ascaris</i>), foreign bodies, cecal/appendiceal tumors (in elderly).</span></p><h3><b>3. Pathophysiology</b></h3><p>Luminal obstruction -&gt; mucus accumulation -&gt; increased intraluminal pressure -&gt; venous congestion -&gt; arterial ischemia -&gt; bacterial translocation -&gt; gangrene and perforation.</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Classic Migration:</b> Dull periumbilical visceral pain (T10 dermatome) shifting within 12–24 hours to sharp somatic pain in the <b>RLQ</b> (Right Lower Quadrant / <b>McBurney’s point</b>).</li>\n<li class=\"l1\">Anorexia (classic!), nausea, low-grade fever.</li>\n<li class=\"l1\"><b>Exam Signs:</b> McBurney’s point tenderness, rebound tenderness (Blumberg’s sign), <b>Rovsing’s sign</b> (LLQ palpation causes RLQ pain), <b>Psoas sign</b> (retrocecal appendix), <b>Obturator sign</b> (pelvic appendix).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Clinical Scoring:</b> <b>Alvarado Score (MANTRELS)</b> — Migration, Anorexia, Nausea, Tenderness RLQ, Rebound, Elevated temp, Leukocytosis, Shift to left.</li>\n<li class=\"l1\"><b>Labs:</b> <mark class=\"hl mech\"><b>CBC</b></mark> (leukocytosis with neutrophilia), <mark class=\"hl mech\"><b>CRP</b></mark> , <b>Urine Analysis</b> (to rule out UTI/stone), <mark class=\"hl mech\"><b>Urine β-hCG</b></mark> (MANDATORY in ALL females of childbearing age to rule out ectopic pregnancy!).</li>\n<li class=\"l1\"><b>Imaging:</b></li>\n<li class=\"l2\"><b>Abdominal Ultrasound</b> (First-line in children, young adults, and pregnancy — non-compressible blind-ending tubular structure &gt; 6 mm).</li>\n<li class=\"l2\"><b>CT Abdomen with Contrast</b> (Gold standard in non-pregnant adults with equivocal findings).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Mesenteric adenitis (children post-URTI), Ectopic pregnancy / Ovarian torsion / <b>PID</b> (Pelvic Inflammatory Disease), Right ureteric stone, Meckel’s diverticulitis, Crohn’s ileitis, Testicular torsion.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\">Appendiceal perforation -&gt; localized appendiceal abscess/phlegmon OR diffuse peritonitis; portal vein pylephlebitis.</li>\n</ul><h3><b>8. Treatment</b></h3><ul>\n<li class=\"l1\"><b>NPO</b>, IV fluids, analgesia (does NOT mask diagnosis!), preoperative IV antibiotics covering Gram-negatives + anaerobes (e.g., Cefoxitin OR Ceftriaxone + Metronidazole).</li>\n<li class=\"l1\"><b>Definitive:</b> <mark class=\"hl rx\"><b>Laparoscopic Appendectomy</b></mark> (emergent).</li>\n<li class=\"l1\"><i>(If perforated with well-formed appendiceal mass/abscess without diffuse peritonitis -&gt; conservative IV antibiotics + percutaneous drainage, followed by interval appendectomy).</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u26\">← Case 6</button><button class=\"nv\" data-u=\"u28\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u28\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Upper Gastrointestinal Bleeding (UGIB)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Upper+Gastrointestinal+Bleeding+%28UGIB%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Bleeding originating proximal to the <b>Ligament of Treitz</b> (esophagus, stomach, or duodenum). Critically divided in Egypt into <b>Non-Variceal</b> vs. <b>Variceal</b> (due to high prevalence of cirrhosis from <b>HCV</b>/Schistosomiasis).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Non-Variceal Causes (~80% globally, ~50–60% in Egyptian liver centers):</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Peptic Ulcer Disease</b></mark> (#1 non-variceal cause).</li>\n<li class=\"l2\">Erosive gastritis / esophagitis (NSAIDs).</li>\n<li class=\"l2\"><b>Mallory-Weiss Tear</b> (mucosal tear at gastroesophageal junction from forceful retching).</li>\n<li class=\"l2\">Dieulafoy lesion, Gastric malignancy, <b>AVMs</b>.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Variceal Causes (Extremely Common in Egypt):</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Esophageal Varices</b></mark> &amp; <b>Gastric Varices</b> secondary to Portal Hypertension (Liver Cirrhosis).</li>\n</ul><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Hematemesis</b> (bright red blood or \"coffee-ground\" emesis).</li>\n<li class=\"l1\"><b>Melena</b> (black, tarry, foul-smelling stool — requires ≥ 50–100 mL blood).</li>\n<li class=\"l1\"><b>Hematochezia</b> (bright red rectal bleeding occurs in ~10–15% of massive rapid UGIB with hemodynamic instability!).</li>\n<li class=\"l1\">Signs of hypovolemia: Tachycardia, orthostatic hypotension, pallor, syncope, cold extremities.</li>\n<li class=\"l1\">Look for <b>stigmata of chronic liver disease</b> (jaundice, ascites, spider angiomata, splenomegaly, palmar erythema) -&gt; immediately raises suspicion of <b>Variceal Bleed</b>!</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Immediate Labs:</b> <mark class=\"hl mech\"><b>CBC</b></mark> (note: acute hemoglobin may initially be normal before hemodilution!), <mark class=\"hl rx\"><b>Type &amp; Cross-match</b></mark> , <mark class=\"hl mech\"><b>PT/INR</b></mark> (Prothrombin Time / International Normalized Ratio), <mark class=\"hl mech\"><b>LFTs</b></mark> (Liver Function Tests), <b>KFTs</b> (Kidney Function Tests — elevated <b>BUN</b>-to-Creatinine ratio &gt; 30:1 due to blood protein digestion in gut!), Electrolytes.</li>\n<li class=\"l1\"><b>Risk Stratification:</b> <b>Glasgow-Blatchford Score</b> (predicts need for intervention).</li>\n<li class=\"l1\"><b>Diagnostic &amp; Therapeutic Gold Standard:</b> <mark class=\"hl rx\"><b>Urgent EGD</b></mark> within <b>12–24 hours</b> (within 12 hours if variceal suspected) after hemodynamic stabilization.</li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\">Hemorrhagic shock, Aspiration pneumonia, <mark class=\"hl lab\"><b>AKI</b></mark> , <mark class=\"hl lab\"><b>Hepatic Encephalopathy</b></mark> (precipitated by blood protein load in cirrhotics), <mark class=\"hl lab\"><b>SBP</b></mark> (Spontaneous Bacterial Peritonitis).</li>\n</ul><h3><b>6. Treatment (Step-by-Step Emergency Protocol)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Resuscitation (ABCDE) FIRST:</b></span></p>\n<ul>\n<li class=\"l2\">Two large-bore IV cannulas (16–18G).</li>\n<li class=\"l2\">Isotonic crystalloids (Normal Saline / Ringer’s).</li>\n<li class=\"l2\"><b>Restrictive Blood Transfusion:</b> Transfuse packed <b>RBCs</b> if <b>Hb &lt; 7 g/dL</b> (or &lt; 8–9 g/dL in <mark class=\"hl lab\"><b>CAD</b></mark> / active massive hemorrhage) — <i>avoid over-transfusion in variceal bleeds as it increases portal pressure!</i></li>\n<li class=\"l2\">Correct coagulopathy if actively bleeding (Fresh Frozen Plasma / Vitamin K if <mark class=\"hl mech\"><b>INR</b></mark> elevated; Platelets if &lt; 50,000).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Medical Therapy BEFORE Endoscopy:</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><b>IV PPI</b></mark> (for ALL UGIB): e.g., Pantoprazole or Esomeprazole 80 mg IV bolus followed by 8 mg/hr infusion (or 40 mg IV BID).</li>\n<li class=\"l2\"><b>IF Cirrhosis / Variceal Bleed Suspected, ADD IMMEDIATELY:</b></li>\n<li class=\"l1\"><b>Vasoactive Agent:</b> IV <mark class=\"hl rx\"><b>Octreotide</b></mark> (50 mcg bolus, then 50 mcg/hr infusion) or <mark class=\"hl rx\"><b>Terlipressin</b></mark> (for 3–5 days).</li>\n<li class=\"l1\"><b>Prophylactic Antibiotic:</b> IV <mark class=\"hl rx\"><b>Ceftriaxone 1 g/day</b></mark> for 5–7 days (prevents <mark class=\"hl lab\"><b>SBP</b></mark> and reduces mortality!).</li>\n<li class=\"l1\"><b>Lactulose</b> via <b>NG</b> (Nasogastric) tube or orally once stable to prevent Hepatic Encephalopathy.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Endoscopic Therapy:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Variceal:</i> <b>Endoscopic Variceal Band Ligation (EVBL)</b> (or cyanoacrylate glue for gastric varices).</li>\n<li class=\"l2\"><i>Non-Variceal Ulcer:</i> Epinephrine injection + thermal coagulation or hemostatic clips.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Refractory Bleeding:</b> Sengstaken-Blakemore tube (temporary bridge) -&gt; <b>TIPS</b> (Transjugular Intrahepatic Portosystemic Shunt) or arterial embolization/surgery.</span></p>\n<p>[Image Reference Suggestion]: Endoscopic comparison showing a <b>Bleeding Peptic Ulcer (Forrest Ia)</b> vs. <mark class=\"hl lab\"><b>Esophageal Varices with Band Ligation</b></mark> .</p><nav class=\"un\"><button class=\"nv\" data-u=\"u27\">← Case 7</button><button class=\"nv\" data-u=\"u29\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u29\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Metabolic Dysfunction-Associated Steatotic Liver Disease (MASLD / NAFLD)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Metabolic+Dysfunction-Associated+Steatotic+Liver+Disease+%28MASLD+%2F+NAFLD%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><mark class=\"hl lab\"><b>MASLD</b></mark> (formerly <mark class=\"hl lab\"><b>NAFLD</b></mark> — Non-Alcoholic Fatty Liver Disease) is hepatic steatosis (&gt; 5% fat accumulation in hepatocytes) diagnosed in the presence of ≥ 1 cardiometabolic risk factor without significant alcohol consumption or other secondary causes. Ranges from simple steatosis to <b>MASH</b> (Metabolic Dysfunction-Associated Steatohepatitis), fibrosis, and cirrhosis.</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Metabolic Syndrome Components (Primary Drivers):</b> Obesity (central adiposity), <mark class=\"hl lab\"><b>T2DM</b></mark> (Type 2 Diabetes Mellitus) / insulin resistance, Dyslipidemia (high triglycerides, low HDL), Hypertension.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Secondary Causes of Steatosis (Must Exclude):</b> Significant alcohol use, <b>HCV</b> (especially genotype 3), drugs (Amiodarone, Tamoxifen, Methotrexate, Corticosteroids), rapid weight loss / starvation.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Usually <b>asymptomatic</b> (incidental finding of \"bright liver\" on ultrasound or mildly elevated <mark class=\"hl mech\"><b>ALT/AST</b></mark> ).</li>\n<li class=\"l1\">Occasional dull <b>RUQ</b> discomfort or fatigue.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> Mildly elevated <mark class=\"hl mech\"><b>ALT &gt; AST</b></mark> (typically &lt; 300 U/L; note: ratio flips to AST &gt; ALT once cirrhosis develops!), fasting glucose, <mark class=\"hl mech\"><b>HbA1c</b></mark> , lipid profile. Exclude viral hepatitis (<mark class=\"hl mech\"><b> HBsAg</b></mark> , <b>Anti-HCV</b>) and autoimmune hepatitis.</li>\n<li class=\"l1\"><b>Imaging:</b> <b>Abdominal Ultrasound</b> (hyperechoic \"bright\" liver).</li>\n<li class=\"l1\"><b>Non-Invasive Fibrosis Assessment:</b></li>\n<li class=\"l2\"><b>FIB-4 Score</b> (Age, AST, ALT, Platelets).</li>\n<li class=\"l2\"><b>Transient Elastography (FibroScan)</b> — assesses liver stiffness (fibrosis) and <mark class=\"hl lab\"><b>CAP</b></mark> (steatosis).</li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\">Progression to <b>MASH</b>, liver cirrhosis, <mark class=\"hl lab\"><b>HCC</b></mark> (Hepatocellular Carcinoma), and <b>Cardiovascular Disease</b> (#1 cause of death in MASLD patients!).</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Cornerstone = Weight Loss &amp; Exercise:</b></li>\n<li class=\"l2\"><b>7–10% total body weight loss</b> reverses steatohepatitis and improves fibrosis!</li>\n<li class=\"l2\">Mediterranean diet, avoid fructose/sugary beverages, 150 min/week aerobic + resistance exercise.</li>\n<li class=\"l1\"><b>Manage Cardiometabolic Comorbidities:</b> Statins are <b>SAFE and recommended</b> in MASLD/compensated cirrhosis!</li>\n<li class=\"l1\"><b>Pharmacotherapy (For biopsy-proven MASH / significant fibrosis):</b> <mark class=\"hl rx\"><b>GLP-1</b></mark> receptor agonists (Semaglutide — improves MASH and weight), <b>Pioglitazone</b> (in T2DM), <b>Vitamin E</b> (800 IU/day in non-diabetic biopsy-proven MASH), <b>Resmetirom</b> (thyroid hormone receptor-beta agonist).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u28\">← Case 8</button><button class=\"nv\" data-u=\"u30\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u30\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Viral Hepatitis (ACUTE HAV/HBV &amp; CHRONIC HBV/HCV IN EGYPT)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Viral+Hepatitis+%28ACUTE+HAV%2FHBV+%26+CHRONIC+HBV%2FHCV+IN+EGYPT%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Viral infection causing hepatocellular inflammation and necrosis.</p>\n<ul>\n<li class=\"l1\"><i>Fecal-Oral (Acute only, no chronicity):</i> <b>HAV</b> (Hepatitis A Virus), <b>HEV</b> (Hepatitis E Virus — high mortality in pregnant women!).</li>\n<li class=\"l1\"><i>Parenteral / Blood / Sexual / Vertical (Can cause chronicity &amp; cirrhosis):</i> <b>HBV</b> (Hepatitis B Virus), <b>HCV</b> (Hepatitis C Virus), <b>HDV</b> (Hepatitis D Virus — requires HBV).</li>\n</ul><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Acute Viral Hepatitis (HAV / Acute HBV):</b></mark></li>\n<li class=\"l2\"><i>Prodromal phase:</i> Fever, malaise, anorexia, nausea, <b>distaste for cigarettes</b> (classic!), RUQ ache.</li>\n<li class=\"l2\"><i>Icteric phase:</i> Jaundice, dark tea-colored urine, pale stools, tender hepatomegaly.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Chronic Viral Hepatitis (HBV / HCV):</b></mark> Usually <b>asymptomatic</b> for decades until cirrhosis or extrahepatic manifestations appear (e.g., HCV -&gt; Mixed Cryoglobulinemia, Porphyria Cutanea Tarda, Membranoproliferative <b>GN</b> [Glomerulonephritis]).</li>\n</ul><h3><b>3. Investigations &amp; Serology Interpretation</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>LFTs:</b></mark> Markedly elevated <mark class=\"hl mech\"><b>AST &amp; ALT</b></mark> (often &gt; 1,000 U/L in acute hepatitis; mild/fluctuating in chronic).</li>\n<li class=\"l1\"><b>Acute HAV:</b> <b>Anti-HAV IgM (+)</b>. (Anti-HAV IgG = past infection/immunity).</li>\n<li class=\"l1\"><b>HBV Serology Panel:</b></li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>HBsAg (+):</b></mark> Active infection (Acute if &lt; 6 months; Chronic if &gt; 6 months).</li>\n<li class=\"l2\"><b>Anti-HBc IgM (+):</b> <mark class=\"hl lab\"><b>Acute</b></mark> HBV (also fills the \"window period\").</li>\n<li class=\"l2\"><b>Anti-HBs (+):</b> Immunity (from vaccine if Anti-HBc is negative; from resolved natural infection if Anti-HBc IgG is positive).</li>\n<li class=\"l2\"><b>HBeAg (+) &amp; High HBV DNA:</b> High infectivity and active viral replication.</li>\n<li class=\"l1\"><b>HCV Diagnosis:</b></li>\n<li class=\"l2\">Screening: <b>Anti-HCV Antibody</b>.</li>\n<li class=\"l2\">Confirmation of Active Infection: <b>HCV RNA PCR</b> (Polymerase Chain Reaction — <i>crucial in Egypt because millions cured via the \"100 Million Health\" campaign remain Anti-HCV Ab positive for life despite negative PCR!</i>).</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Acute HAV / Acute uncomplicated HBV:</b> Supportive care (hydration, rest, avoid hepatotoxins like paracetamol/alcohol). <i>Acute fulminant HBV (coagulopathy INR &gt; 1.5 or encephalopathy)</i> -&gt; Nucleos(t)ide analogue (<b>Entecavir</b> or <b>Tenofovir</b>) + liver transplant evaluation.</li>\n<li class=\"l1\"><b>Chronic HBV:</b> Indicated if cirrhosis, active hepatitis (elevated ALT + high HBV DNA ≥ 2,000–20,000 IU/mL), or family history of HCC -&gt; <b>Tenofovir</b> (<b>TDF</b> / <b>TAF</b>) or <b>Entecavir</b> (high barrier to resistance).</li>\n<li class=\"l1\"><b>Chronic HCV (Curative &gt; 95–98% SVR!):</b> Pan-genotypic <b>DAAs</b> (Direct-Acting Antivirals), e.g., <b>Sofosbuvir + Daclatasvir</b> (widely used in Egypt) or <b>Sofosbuvir + Velpatasvir</b> for 12 weeks.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u29\">← Case 9</button><button class=\"nv\" data-u=\"u31\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u31\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Liver Cirrhosis &amp; Portal Hypertension</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Liver+Cirrhosis+%26+Portal+Hypertension\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Irreversible, diffuse hepatic fibrosis with regenerative nodule formation distorting normal liver architecture, leading to <b>hepatocellular dysfunction</b> and <b>portal hypertension</b>.</p><h3><b>2. Etiology (Separated — Egyptian Context)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Chronic Viral Hepatitis:</b></mark> Chronic <b>HCV</b> (historically #1 cause in Egypt) and Chronic <b>HBV</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Metabolic:</b> <mark class=\"hl lab\"><b>MASLD / MASH</b></mark> (rapidly rising #1 global/future cause).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Alcoholic Liver Disease.</b></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Vascular / Parasitic Overlap:</b> <i>Schistosoma mansoni</i> (causes periportal fibrosis and severe pre-sinusoidal portal hypertension), <b>Budd-Chiari Syndrome</b> (hepatic vein thrombosis).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Autoimmune / Genetic / Cholestatic:</b> Autoimmune hepatitis, <mark class=\"hl lab\"><b>PBC</b></mark> , <mark class=\"hl lab\"><b>PSC</b></mark> , Wilson’s disease (young patient &lt; 40, Kayser-Fleischer rings, low ceruloplasmin), Hemochromatosis.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Compensated Cirrhosis:</b> May be asymptomatic or have fatigue, spider angiomata, palmar erythema, gynecomastia, testicular atrophy, Dupuytren’s contracture, hepatosplenomegaly.</li>\n<li class=\"l1\"><b>Decompensated Cirrhosis (Any of 4 Events):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Ascites.</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Variceal Bleeding.</b></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Hepatic Encephalopathy.</b></mark></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Jaundice.</b></span></p><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> Thrombocytopenia (earliest sign of portal hypertension due to splenic sequestration!), hypoalbuminemia, prolonged <mark class=\"hl mech\"><b>PT/INR</b></mark> , elevated bilirubin, <mark class=\"hl mech\"><b>AST &gt; ALT</b></mark> .</li>\n<li class=\"l1\"><b>Imaging:</b> Abdominal Ultrasound (coarse shrunken liver, irregular surface, splenomegaly, dilated portal vein &gt; 13 mm, ascites).</li>\n<li class=\"l1\"><b>Staging:</b> <b>Child-Pugh Score</b> (<b>A, B, C</b> — Bilirubin, Albumin, INR, Ascites, Encephalopathy) and <b>MELD Score</b> (for transplant priority).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Surveillance (Mandatory in ALL Cirrhotics):</b></mark></li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>Abdominal Ultrasound +/- AFP</b></mark> (Alpha-Fetoprotein) <b>every 6 months</b> to screen for <mark class=\"hl lab\"><b>HCC</b></mark> !</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>EGD</b></mark> screening for esophageal varices.</li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\">Ascites &amp; <mark class=\"hl lab\"><b>SBP</b></mark> , Variceal hemorrhage, Hepatic Encephalopathy, <b>Hepatorenal Syndrome (HRS)</b>, <b>Hepatopulmonary Syndrome</b>, <mark class=\"hl lab\"><b>HCC</b></mark> (Hepatocellular Carcinoma), Portal vein thrombosis.</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\">Treat underlying cause (DAAs for HCV, Tenofovir/Entecavir for HBV, weight loss, stop alcohol).</li>\n<li class=\"l1\">Avoid hepatotoxins (<mark class=\"hl rx\"><b> NSAIDs</b></mark> , sedatives/benzodiazepines, alcohol).</li>\n<li class=\"l1\"><b>Portal Hypertension Variceal Prophylaxis:</b> Non-selective Beta-Blockers (<mark class=\"hl rx\"><b> Carvedilol</b></mark> or <mark class=\"hl rx\"><b>Propranolol</b></mark> ) or <b>EVBL</b>.</li>\n<li class=\"l1\"><b>Definitive Cure for End-Stage Decompensated Cirrhosis:</b> <b>Liver Transplantation</b>.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u30\">← Case 10</button><button class=\"nv\" data-u=\"u32\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u32\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Ascites &amp; Spontaneous Bacterial Peritonitis (SBP)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ascites+%26+Spontaneous+Bacterial+Peritonitis+%28SBP%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><b>Ascites:</b> Pathological accumulation of fluid in the peritoneal cavity.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>SBP:</b></mark> Infection of ascitic fluid without an evident intra-abdominal surgically treatable source (common and fatal complication in cirrhosis).</li>\n</ul><h3><b>2. Etiology of Ascites (Separated by SAAG — Serum-Ascites Albumin Gradient)</b></h3><ul>\n<li class=\"l1\"><b>High SAAG (≥ 1.1 g/dL -&gt; Portal Hypertension):</b></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Liver Cirrhosis</b></mark> (~80% of all ascites), Heart failure (ascitic protein &gt; 2.5 g/dL), Budd-Chiari syndrome, Constrictive pericarditis.</li>\n<li class=\"l1\"><b>Low SAAG (&lt; 1.1 g/dL -&gt; Non-Portal Hypertension):</b></li>\n<li class=\"l2\">Peritoneal carcinomatosis, <b>Tuberculous Peritonitis</b> (important in Egypt!), Nephrotic syndrome, Pancreatitis, Serositis (<mark class=\"hl lab\"><b> SLE</b></mark> ).</li>\n</ul><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Ascites:</b> Progressive abdominal distension, flank bulging, <b>shifting dullness</b> (detects &gt; 1,500 mL), <b>fluid thrill</b>, umbilical hernia.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>SBP:</b></mark> May present with fever, abdominal pain/tenderness, OR <b>silently</b> as unexplained <mark class=\"hl lab\"><b>Hepatic Encephalopathy</b></mark> , <mark class=\"hl lab\"><b>AKI</b></mark> , or hypotension!</li>\n</ul>\n<p><mark class=\"hl lab\"><b>4. Investigations (Diagnostic Paracentesis is MANDATORY in ALL new-onset ascites or hospitalized cirrhotics!)</b></mark></p>\n<ul>\n<li class=\"l1\">Send ascitic fluid for:</li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Cell Count &amp; Differential:</b> <mark class=\"hl mech\"><b>PMN</b></mark> (Polymorphonuclear leukocyte) count <b>≥ 250 cells/mm³</b> = <mark class=\"hl lab\"><b>DIAGNOSTIC OF SBP</b></mark> (treat immediately, do not wait for cultures!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Ascitic Albumin</b> (simultaneous with Serum Albumin to calculate <b>SAAG</b> = Serum Albumin − Ascitic Albumin) + <b>Total Protein</b> (protein &lt; 1.5 g/dL increases SBP risk).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Culture</b> (inoculate directly into blood culture bottles at bedside — most common organisms: <i>E. coli</i>, <i>Klebsiella</i>, <i>Streptococcus pneumoniae</i>).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Cytology / ADA</b> (Adenosine Deaminase) if low SAAG (malignancy/TB suspected).</span></p><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Uncomplicated Cirrhotic Ascites:</b></li>\n<li class=\"l2\">Dietary sodium restriction (&lt; 2 g/day or &lt; 88 mEq/day).</li>\n<li class=\"l2\"><b>Diuretics (Classic 100:40 Ratio):</b> <mark class=\"hl rx\"><b>Spironolactone 100 mg + Furosemide 40 mg</b></mark> once daily in morning (titrate up maintaining 100:40 ratio up to max 400 mg : 160 mg while monitoring K+ and Creatinine).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Large-Volume Paracentesis (LVP)</b></mark> for tense/refractory ascites: If &gt; 5 L removed, give <b>IV Albumin 6–8 g per liter removed</b> to prevent paracentesis-induced circulatory dysfunction!</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>SBP Treatment (Medical Emergency):</b></mark></li>\n<li class=\"l2\"><b>IV 3rd-Generation Cephalosporin:</b> <mark class=\"hl rx\"><b>Cefotaxime 2 g IV every 8 hours</b></mark> (or Ceftriaxone 2 g IV daily) for 5–7 days.</li>\n<li class=\"l2\"><b>IV Albumin</b> (1.5 g/kg on Day 1 + 1.0 g/kg on Day 3) -&gt; significantly reduces <b>HRS</b> and mortality!</li>\n<li class=\"l2\"><i>Secondary Prophylaxis after SBP:</i> Daily Norfloxacin 400 mg or Ciprofloxacin/TMP-SMX lifelong or until transplant.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u31\">← Case 11</button><button class=\"nv\" data-u=\"u33\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u33\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Hepatic Encephalopathy (HE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hepatic+Encephalopathy+%28HE%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>A potentially reversible spectrum of neuropsychiatric abnormalities occurring in patients with acute or chronic liver dysfunction and/or portosystemic shunting.</p><h3><b>2. Precipitating Factors (Separated — Always Hunt for the Trigger! Mnemonic: \"HEPATIC\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>H</b>emorrhage (<b>GI</b> bleeding — blood is a massive nitrogen/protein load!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>E</b>lectrolyte Imbalance (Hypokalemia, Hyponatremia, Alkalosis — often from excessive diuretics).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>P</b>ortosystemic Shunts (<b>TIPS</b>) / Dehydration / <mark class=\"hl lab\"><b>AKI</b></mark> .</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>A</b>lcohol / Medications (<b>Sedatives, Benzodiazepines, Opioids</b>).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>T</b>rauma / Surgery / Constipation (increased colonic ammonia absorption).</span></p>\n<p class=\"num\"><span class=\"n\">6.</span><span class=\"nt\"><b>I</b>nfection (<mark class=\"hl lab\"><b> SBP</b></mark> , <b>UTI</b>, Pneumonia — #1 precipitant alongside GI bleed!).</span></p>\n<p class=\"num\"><span class=\"n\">7.</span><span class=\"nt\"><b>C</b>ompliance failure (stopping Lactulose).</span></p><h3><b>3. Pathophysiology</b></h3><p>Failure of the cirrhotic liver to clear gut-derived neurotoxins—principally <b>ammonia</b> (produced by colonic bacteria)—allows ammonia to cross the blood-brain barrier, causing astrocyte swelling and <b>GABA</b> (Gamma-Aminobutyric Acid)-ergic neuroinhibition.</p><h3><b>4. Clinical Picture (West Haven Criteria Grades I–IV)</b></h3><ul>\n<li class=\"l1\"><i>Grade I:</i> Mild confusion, euphoria/anxiety, <b>sleep-wake cycle reversal</b> (sleeping by day, awake at night).</li>\n<li class=\"l1\"><i>Grade II:</i> Lethargy, disorientation, inappropriate behavior, <b>Asterixis</b> (\"flapping tremor\" on wrist extension).</li>\n<li class=\"l1\"><i>Grade III:</i> Somnolence to stupor (arousable), marked confusion, slurred speech.</li>\n<li class=\"l1\"><i>Grade IV:</i> <mark class=\"hl lab\"><b>Coma</b></mark> (unresponsive to pain).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Clinical Diagnosis</b> (ammonia levels correlate poorly with severity and are NOT required to diagnose/follow HE in known cirrhosis, though useful to rule out HE if normal!).</li>\n<li class=\"l1\"><b>Workup to Find Precipitant (CRITICAL):</b> <mark class=\"hl mech\"><b>CBC</b></mark> , Electrolytes (<b>K+</b>, <b>Na+</b>), <mark class=\"hl mech\"><b>RFTs</b></mark> , Blood/Urine cultures, Diagnostic Paracentesis (<mark class=\"hl lab\"><b> rule out SBP!</b></mark> ), Chest X-ray, Digital Rectal Exam / occult blood (rule out melena).</li>\n<li class=\"l1\"><b>CT Brain:</b> Only if focal neurological deficits or trauma suspected (rule out subdural hematoma/stroke).</li>\n</ul><h3><b>6. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Identify &amp; Treat Precipitating Factor Immediately!</b> (Antibiotics for SBP/UTI, stop diuretics, correct hypokalemia, control GI bleed).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Lactulose (First-Line):</b> 15–30 mL orally every 6–8 hours (or via NG tube / retention enema in Grade III–IV), titrated to achieve <b>2–3 soft bowel movements per day</b>. <i>(Mechanism: Acidifies colon, converting absorbable NH3 to non-absorbable NH4+, plus laxative washout).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Rifaximin (Add-on / Secondary Prophylaxis):</b> 550 mg BID (non-absorbable oral antibiotic reducing ammonia-producing gut bacteria).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Nutrition:</b> <b>Do NOT severely restrict dietary protein!</b> Maintain 1.2–1.5 g/kg/day protein (vegetable/dairy proteins preferred over red meat) to prevent muscle wasting (sarcopenia worsens ammonia clearance!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u32\">← Case 12</button><button class=\"nv\" data-u=\"u34\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u34\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Inflammatory Bowel Disease (ULCERATIVE COLITIS &amp; CROHNʼS DISEASE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Inflammatory+Bowel+Disease+%28ULCERATIVE+COLITIS+%26+CROHN%CA%BCS+DISEASE%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic, relapsing immune-mediated inflammation of the <b>GI</b> tract resulting from dysregulated mucosal immune response to gut microbiota in genetically susceptible hosts.</p><h3><b>2. Comparison: Ulcerative Colitis (UC) vs. Crohn’s Disease (CD)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><mark class=\"hl lab\"><b>Ulcerative Colitis (UC)</b></mark></p></th><th><p><b>Crohn’s Disease (CD)</b></p></th></tr><tr><td><p><b>Distribution</b></p></td><td><p><b>Rectum ALWAYS involved</b>; spreads <b>continuously </b>proximally (colon only)</p></td><td><p><b>Mouth to Anus</b> (most common: terminal ileum + colon); <b>skip lesions</b>; rectal sparing</p></td></tr><tr><td><p><b>Depth of Inflammation</b></p></td><td><p><b>Mucosal &amp; Submucosal</b> only</p></td><td><p><b>Transmural</b> (full thickness -&gt; fistulas, strictures, abscesses!)</p></td></tr><tr><td><p><b>Classic Presentation</b></p></td><td><p>Bloody diarrhea + mucus, tenesmus, urgency, LLQ pain</p></td><td><p>Non-bloody watery diarrhea, RLQ pain/mass, weight loss, <b>perianal fistulas/tags</b></p></td></tr><tr><td><p><b>Endoscopy / Pathology</b></p></td><td><p>Friable mucosa, continuous ulcers, <b>pseudopolyps</b>, crypt abscesses</p></td><td><p><b>\"Cobblestone\"</b> mucosa, linear aphthous ulcers, <b>non-caseating granulomas</b></p></td></tr><tr><td><p><b>Imaging</b></p></td><td><p><b>\"Lead-pipe\" colon</b> (loss of haustra)</p></td><td><p><b>\"String sign\"</b> (narrowed terminal ileum), creeping fat</p></td></tr><tr><td><p><b>Smoking Effect</b></p></td><td><p><b>Protective</b> (flares often after quitting)</p></td><td><p><b>Worsens</b> disease &amp; flares!</p></td></tr></table><h3><b>3. Extraintestinal Manifestations</b></h3><ul>\n<li class=\"l1\"><b>Parallel to Disease Activity:</b> Peripheral arthritis, Erythema nodosum, Aphthous stomatitis, Episcleritis.</li>\n<li class=\"l1\"><b>Independent of Disease Activity:</b> <mark class=\"hl lab\"><b>PSC</b></mark> (Primary Sclerosing Cholangitis — strongly linked to UC), Ankylosing spondylitis, Uveitis, Pyoderma gangrenosum.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> <mark class=\"hl mech\"><b>CBC</b></mark> (anemia), <mark class=\"hl mech\"><b>CRP / ESR</b></mark> , <b>Fecal Calprotectin</b> (markedly elevated — distinguishes IBD from IBS!), Stool cultures/ova/parasites (MUST exclude infection like <i>E. histolytica</i> or <i>C. diff</i> before starting steroids!).</li>\n<li class=\"l1\"><b>Gold Standard:</b> <b>Ileocolonoscopy with Biopsies</b> (+ <b>CT/MR Enterography</b> for small bowel Crohn’s).</li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\"><b>UC:</b> <b>Toxic Megacolon</b> (colon &gt; 6 cm + fever/tachycardia — surgical emergency!), massive hemorrhage, <mark class=\"hl lab\"><b>Colorectal Cancer</b></mark> (screen via colonoscopy starting 8 years after diagnosis).</li>\n<li class=\"l1\"><b>CD:</b> Bowel obstruction (strictures), fistulas (enterovesical, enterocutaneous, perianal), intra-abdominal abscesses, malabsorption (Vitamin B12/iron/bile salt deficiency).</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Mild-to-Moderate UC:</b> <b>5-ASA</b> (<b>Mesalamine</b>) oral + rectal suppositories/enemas.</li>\n<li class=\"l1\"><b>Acute Moderate-Severe Flares (UC or CD):</b> Systemic <mark class=\"hl rx\"><b>Corticosteroids</b></mark> (Oral Prednisone or IV Hydrocortisone/Methylprednisolone) for induction ONLY (never maintenance!).</li>\n<li class=\"l1\"><b>Maintenance / Steroid-Sparing:</b> Immunomodulators (<mark class=\"hl rx\"><b> Azathioprine</b></mark> , 6-Mercaptopurine, Methotrexate) or <b>Biologics</b> (Anti-TNF: <b>Infliximab</b>, <b>Adalimumab</b>; Anti-integrin: Vedolizumab; Anti-IL-12/23: Ustekinumab).</li>\n<li class=\"l1\"><b>Surgery:</b> <i>Total Proctocolectomy</i> is <b>curative</b> in UC (toxic megacolon, dysplasia, refractory disease); surgery in CD is reserved strictly for complications (strictures/abscesses) as disease recurs!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u33\">← Case 13</button><button class=\"nv\" data-u=\"u35\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u35\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Hemorrhoids, Anal Fissure &amp; Lower GI Bleeding Approach</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hemorrhoids%2C+Anal+Fissure+%26+Lower+GI+Bleeding+Approach\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Separated Causes</b></h3><ul>\n<li class=\"l1\"><b>Hemorrhoids:</b> Engorged vascular cushions in the anal canal (<b>Internal</b> = above dentate line, <b>painless</b> bright red bleeding on toilet paper/dripping; <b>External</b> = below dentate line, painful if <b>thrombosed</b>).</li>\n<li class=\"l2\"><i>Causes:</i> Chronic constipation/straining, pregnancy, prolonged sitting on toilet, portal hypertension (anorectal varices must be distinguished!).</li>\n<li class=\"l1\"><b>Anal Fissure:</b> Longitudinal tear in the anodermal mucosa distal to the dentate line (90% <b>posterior midline</b>; if lateral/multiple -&gt; suspect <b>Crohn’s disease</b>, TB, or malignancy!).</li>\n<li class=\"l2\"><i>Causes:</i> Hard stool trauma + internal anal sphincter hypertonia/ischemia.</li>\n</ul><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Internal Hemorrhoids:</b> Painless bright red blood coating stool/dripping into bowl, prolapse (Grades I–IV).</li>\n<li class=\"l1\"><b>Thrombosed External Hemorrhoid:</b> Sudden severe constant anal pain + tender bluish perianal lump.</li>\n<li class=\"l1\"><b>Anal Fissure:</b> Severe sharp <b>\"tearing/glass-passing\"</b> pain during AND lasting hours after defecation + streaks of bright red blood on tissue + sentinel skin tag (if chronic).</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 3. Approach &amp; Red Flag Rule for Lower GI Bleeding (LGIB)</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>CRITICAL RULE:</b> Never blindly attribute rectal bleeding to hemorrhoids in a patient <b>&gt; 45–50 years</b>, or with <b>weight loss, change in bowel habits, anemia, or family history of colon cancer</b> -&gt; Perform <b>Colonoscopy</b> to rule out <b>Colorectal Carcinoma</b>, Diverticulosis, or Angiodysplasia!</li>\n<li class=\"l1\">Physical exam: Inspection + <mark class=\"hl lab\"><b>DRE</b></mark> (Digital Rectal Exam) + Anoscopy (defer DRE if acute severe fissure pain!).</li>\n</ul></div></div><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Conservative (First-line for both):</b> High-fiber diet (25–35 g/day ), adequate water hydration, stool softeners (e.g., Psyllium/Lactulose), <b>warm Sitz baths</b> (15–20 min BID–TID), avoid straining.</li>\n<li class=\"l1\"><b>Hemorrhoids:</b> Topical hydrocortisone/lidocaine short-term; <b>Rubber Band Ligation</b> (Grades II–III internal); Hemorrhoidectomy (Grade IV or refractory); Excision within 72 hours for painful thrombosed external hemorrhoid.</li>\n<li class=\"l1\"><b>Anal Fissure:</b> Topical <mark class=\"hl rx\"><b>Nitroglycerin (GTN 0.2–0.4%)</b></mark> or <mark class=\"hl rx\"><b>Diltiazem 2% / Nifedipine</b></mark> ointment (relaxes internal sphincter &amp; improves blood flow); <b>Lateral Internal Sphincterotomy</b> if chronic/refractory.</li>\n</ul>\n<p class=\"muted\"><i>End of Part 3A</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u34\">← Case 14</button><button class=\"nv\" data-u=\"u36\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u36\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Type 2 Diabetes Mellitus (T2DM) — Outpatient Management</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Type+2+Diabetes+Mellitus+%28T2DM%29+%E2%80%94+Outpatient+Management\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><mark class=\"hl lab\"><b>T2DM</b></mark> (Type 2 Diabetes Mellitus) is a chronic metabolic disorder characterized by hyperglycemia resulting from progressive <b>insulin resistance</b> combined with a relative defect in pancreatic <b>beta-cell insulin secretion</b>.</p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Genetic Predisposition:</b> Strong polygenic inheritance (positive family history in 1st-degree relatives).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Lifestyle &amp; Metabolic Drivers:</b> Central obesity (visceral adiposity releases free fatty acids and inflammatory cytokines), physical inactivity, high-caloric/refined-carbohydrate diet.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Secondary / Hormonal / Drug Causes of Hyperglycemia:</b> Corticosteroids, atypical antipsychotics, thiazide diuretics, Cushing’s syndrome, acromegaly, gestational diabetes history, <mark class=\"hl lab\"><b>PCOS</b></mark> (Polycystic Ovary Syndrome).</span></p>\n<p><b>3. Diagnostic Criteria (ADA — American Diabetes Association: Any 1 confirmed on repeat testing, or 1 if classic hyperglycemic symptoms exist)</b></p>\n<ul>\n<li class=\"l1\"><b>FPG</b> (Fasting Plasma Glucose, ≥ 8 hrs fast) <b>≥ 126 mg/dL</b>.</li>\n<li class=\"l1\"><b>2-Hour PG</b> during <b>75-g OGTT</b> (Oral Glucose Tolerance Test) <b>≥ 200 mg/dL</b>.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>HbA1c</b></mark> (Glycated Hemoglobin) <b>≥ 6.5%</b> <i>(note: unreliable in hemoglobinopathies like Thalassemia, severe anemia, or recent blood transfusion!).</i></li>\n<li class=\"l1\"><b>Random Plasma Glucose ≥ 200 mg/dL</b> + classic symptoms (polyuria, polydipsia, unexplained weight loss).</li>\n<li class=\"l1\"><i>(Prediabetes: FPG 100–125 mg/dL, 2-hr PG 140–199 mg/dL, or HbA1c 5.7–6.4%).</i></li>\n</ul><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Often <b>asymptomatic</b> for years (diagnosed on routine screening).</li>\n<li class=\"l1\">Classic triad: Polyuria, polydipsia, polyphagia + fatigue, blurred vision, slow-healing wounds, recurrent candidal infections (balanitis/vulvovaginitis) or <b>UTIs</b> (Urinary Tract Infections).</li>\n<li class=\"l1\">Physical signs of insulin resistance: <b>Acanthosis nigricans</b> (velvety hyperpigmented plaques on neck/axilla), central obesity.</li>\n</ul><h3><b>5. Investigations &amp; Annual Screening</b></h3><ul>\n<li class=\"l1\">Baseline &amp; Monitoring: <mark class=\"hl mech\"><b>HbA1c</b></mark> every 3–6 months (general target <b>&lt; 7.0%</b>; &lt; 7.5–8.0% in frail elderly), Fasting Lipid Profile, <mark class=\"hl mech\"><b>LFTs</b></mark> (Liver Function Tests), <mark class=\"hl mech\"><b>RFTs</b></mark> (Renal Function Tests: Serum Creatinine + <b>eGFR</b> [Estimated Glomerular Filtration Rate]).</li>\n<li class=\"l1\">Annual Complication Screening: <b>UACR</b> (Urine Albumin-to-Creatinine Ratio for diabetic nephropathy), Dilated Fundoscopic Eye Exam (retinopathy), 10-g Monofilament Foot Exam (neuropathy), <mark class=\"hl mech\"><b>ECG</b></mark> (Electrocardiogram).</li>\n</ul><h3><b>6. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>T1DM</b></mark> (Type 1 Diabetes Mellitus — young, lean, acute onset, positive anti-GAD65/IA-2 antibodies, <mark class=\"hl lab\"><b>DKA</b></mark> ), <b>LADA</b> (Latent Autoimmune Diabetes in Adults), <b>MODY </b>(Maturity-Onset Diabetes of the Young), Drug-induced hyperglycemia.</li>\n</ul><h3><b>7. Complications</b></h3><ul>\n<li class=\"l1\"><b>Microvascular:</b> Diabetic Retinopathy (#1 cause of adult blindness), Diabetic Nephropathy (#1 cause of <mark class=\"hl mech\"><b>ESRD</b></mark> [End-Stage Renal Disease]), Diabetic Neuropathy (symmetric \"stocking-glove\" sensory loss, gastroparesis, erectile dysfunction).</li>\n<li class=\"l1\"><b>Macrovascular:</b> <mark class=\"hl lab\"><b>CAD</b></mark> (Coronary Artery Disease — silent myocardial ischemia!), Cerebrovascular Stroke, <mark class=\"hl lab\"><b>PAD</b></mark> (Peripheral Arterial Disease) &amp; Diabetic Foot Ulcers.</li>\n</ul><h3><b>8. Treatment (Modern Organ-Protective Approach)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Lifestyle (Foundation):</b> Medical nutrition therapy (5–10% weight loss), 150 min/week moderate aerobic exercise + resistance training, smoking cessation.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>First-Line Pharmacotherapy:</b> <mark class=\"hl rx\"><b>Metformin</b></mark> (start 500 mg daily with meal, titrate up to 1,000 mg <b>BID</b> [Twice Daily]; check <b>eGFR</b> — reduce dose if eGFR 30–44, <b>CONTRAINDICATED if eGFR &lt; 30 mL/min/1.73 m²</b> due to lactic acidosis risk; monitor Vitamin B12 levels long-term!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl mech\"><b>Cardiorenal Organ-Protective Add-On (Independent of HbA1c!):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><i>If </i><i><b>ASCVD</b></i><i> (Atherosclerotic Cardiovascular Disease) or High CV Risk:</i> Add <mark class=\"hl rx\"><b>GLP-1 RA</b></mark> (Glucagon-Like Peptide-1 Receptor Agonist, e.g., Liraglutide, Semaglutide) or <b>SGLT2i</b> (Sodium-Glucose Cotransporter-2 Inhibitor, e.g., Empagliflozin, Dapagliflozin).</li>\n<li class=\"l2\"><i>If </i><i><b>HF</b></i><i> (Heart Failure) or </i><mark class=\"hl lab\"><i><b>CKD</b></i></mark><i> (Chronic Kidney Disease, eGFR ≥ 20):</i> Add <b>SGLT2i</b> (Empagliflozin/Dapagliflozin — strongly protective!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Other Agents:</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><b>DPP-4 Inhibitors</b></mark> (Sitagliptin, Vildagliptin — weight-neutral, low hypoglycemia risk; avoid Saxagliptin in HF).</li>\n<li class=\"l2\"><b>Sulfonylureas</b> (Glimepiride, Gliclazide — inexpensive, potent, <i>but cause weight gain and hypoglycemia</i>).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Insulin</b></mark> (Basal insulin e.g. Glargine/Degludec +/- Prandial if HbA1c &gt; 10%, glucose ≥ 300 mg/dL with catabolism/weight loss, or failure of oral/injectable combinations).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Comprehensive Risk Reduction:</b> High/moderate-intensity <mark class=\"hl rx\"><b>Statin</b></mark> (for ages 40–75 or ASCVD), <mark class=\"hl rx\"><b>ACE-i / ARB</b></mark> (if hypertension or albuminuria), <b>BP</b> target &lt; 130/80 mmHg.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u35\">← Case 15</button><button class=\"nv\" data-u=\"u37\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u37\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Diabetic Ketoacidosis (DKA) &amp; Hyperosmolar Hyperglycemic State (HHS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Diabetic+Ketoacidosis+%28DKA%29+%26+Hyperosmolar+Hyperglycemic+State+%28HHS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Life-threatening acute hyperglycemic crises:</p>\n<ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>DKA:</b></mark> Triad of <b>Hyperglycemia</b> (&gt; 200–250 mg/dL; note <i>euglycemic DKA</i> can occur with SGLT2 inhibitors!), <b>Ketosis</b> (ketonemia/ketonuria), and <b>High Anion Gap Metabolic Acidosis</b> (pH &lt; 7.30, HCO3- &lt; 18 mEq/L). Typical of <mark class=\"hl lab\"><b>T1DM</b></mark> , though occurs in T2DM under stress.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>HHS:</b></mark> Extreme hyperglycemia (<b>&gt; 600 mg/dL</b>), severe hyperosmolality (<b>&gt; 320 mOsm/kg</b>), and profound dehydration with <b>minimal/absent ketoacidosis</b> (pH &gt; 7.30, HCO3- &gt; 18 mEq/L). Typical of elderly <mark class=\"hl lab\"><b>T2DM</b></mark> .</li>\n</ul><h3><b>2. Precipitating Factors (Separated — \"5 Is\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>I</b>nfection (#1 overall trigger — Pneumonia, <b>UTI</b>, Sepsis, Diabetic foot).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>I</b>nsulin omission or inadequate dosing (non-compliance, pump failure).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>I</b>nfarction (<mark class=\"hl lab\"><b> MI</b></mark> , Stroke) / Acute Pancreatitis.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>I</b>atrogenic / Drugs (Corticosteroids, Thiazides, <b>SGLT2i</b> [causes euglycemic DKA]).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>I</b>nitial presentation (newly diagnosed T1DM).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>DKA (Rapid onset &lt; 24 hours):</b></mark> Polyuria, polydipsia, nausea, vomiting, <b>abdominal pain</b> (mimics acute abdomen!), <b>Kussmaul respirations</b> (deep rapid hyperventilation to blow off CO2), fruity <b>acetone breath</b>, tachycardia, hypotension, altered mental status.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>HHS (Insidious onset over days–weeks):</b></mark> Extreme dehydration, altered sensorium/coma, focal seizures or stroke-like deficits, NO Kussmaul breathing.</li>\n</ul><h3><b>4. Investigations (Immediate Bedside &amp; Lab Workup)</b></h3><ul>\n<li class=\"l1\">Capillary blood glucose + <mark class=\"hl mech\"><b>ABG / VBG</b></mark> (Arterial / Venous Blood Gas — check pH, HCO3-), Serum <b>Electrolytes</b> (<b>Na+, K+, Cl-</b> to calculate <b>Anion Gap</b> = Na+ − [Cl- + HCO3-]; normal 8–12), <mark class=\"hl mech\"><b>RFTs</b></mark> , Serum/Urine Ketones (β-hydroxybutyrate preferred), <mark class=\"hl mech\"><b>CBC</b></mark> , Blood/Urine Cultures, <mark class=\"hl mech\"><b>ECG</b></mark> (rule out silent MI &amp; check K+ effects!), Chest X-ray.</li>\n<li class=\"l1\"><i>Crucial Formula:</i> <b>Corrected Sodium</b> = Measured Na+ + 0.016 × (Glucose − 100) (or add 1.6 mEq/L per 100 mg/dL glucose above 100).</li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\">Hypokalemia (fatal arrhythmias!), Cerebral edema (especially in children during rapid correction of DKA), Hypoglycemia, Thrombosis/Stroke (especially in HHS), <mark class=\"hl lab\"><b>ARDS</b></mark> .</li>\n</ul><h3><b>6. Treatment (The Golden 4-Step DKA/HHS Protocol)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Aggressive IV Fluids FIRST:</b></span></p>\n<ul>\n<li class=\"l2\"><b>0.9% Normal Saline</b> 1,000 mL (15–20 mL/kg) over the first hour, then 250–500 mL/hr depending on hydration/cardiac status (switch to <b>0.45% Saline</b> if corrected Na+ is normal/high).</li>\n<li class=\"l2\">Once blood glucose drops to <b>200–250 mg/dL</b> (DKA) or <b>250–300 mg/dL</b> (HHS), switch fluids to <b>D5W + 0.45% Saline</b> to prevent hypoglycemia while continuing insulin to clear ketones!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Check Serum Potassium (K+) BEFORE Starting Insulin!</b></mark></span></p>\n<ul>\n<li class=\"l2\">If <b>K+ &lt; 3.3 mEq/L:</b> <b>HOLD INSULIN!</b> Give <b>IV KCl</b> (20–40 mEq/hr) until K+ &gt; 3.3 mEq/L (insulin drives K+ into cells and causes fatal cardiac arrest!).</li>\n<li class=\"l2\">If <b>K+ 3.3 – 5.2 mEq/L:</b> Add 20–30 mEq KCl to each liter of IV fluid (target K+ 4–5 mEq/L).</li>\n<li class=\"l2\">If <b>K+ &gt; 5.2 mEq/L:</b> Hold K+ initially and recheck every 2 hours.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl rx\"><b>IV Regular Insulin Infusion:</b></mark></span></p>\n<ul>\n<li class=\"l2\"><b>0.1 units/kg/hr</b> continuous IV infusion (or 0.1 U/kg IV bolus then 0.1 U/kg/hr).</li>\n<li class=\"l2\"><b>NEVER stop IV insulin when glucose normalizes!</b> Continue until <b>Anion Gap closes</b> (&lt; 12), pH &gt; 7.30, and HCO3- ≥ 18 mEq/L; overlap <b>subcutaneous insulin</b> for <b>1–2 hours BEFORE stopping IV insulin</b> to prevent rebound DKA!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Sodium Bicarbonate:</b> Generally <b>NOT recommended</b> (only consider if life-threatening pH <b>&lt; 6.9</b>). Treat the precipitating infection/trigger!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u36\">← Case 16</button><button class=\"nv\" data-u=\"u38\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u38\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Hypoglycemia</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypoglycemia\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Defined clinically by <b>Whipple’s Triad</b>: (1) Symptoms consistent with hypoglycemia, (2) Documented low plasma glucose (<b>&lt; 70 mg/dL</b> alert value; <b>&lt; 54 mg/dL</b> clinically significant), and (3) Resolution of symptoms after glucose administration.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>In Diabetic Patients (Most Common):</b> Excess insulin or sulfonylurea dose, missed/delayed meal after dose, unaccustomed exercise, <mark class=\"hl lab\"><b>AKI/CKD</b></mark> (reduced renal insulin &amp; sulfonylurea clearance!), alcohol intake.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>In Non-Diabetic Patients:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Drugs:</i> Accidental/factitious insulin or sulfonylurea ingestion, Quinine, Pentamidine.</li>\n<li class=\"l2\"><i>Critical Illness / Organ Failure:</i> Severe liver failure, sepsis, adrenal insufficiency, malnutrition.</li>\n<li class=\"l2\"><i>Endogenous Hyperinsulinism:</i> <mark class=\"hl rx\"><b>Insulinoma</b></mark> (fasting hypoglycemia with high insulin + <b>high C-peptide</b>), post-bariatric surgery dumping syndrome.</li>\n</ul><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Autonomic (Neurogenic) Symptoms (&lt; 60 mg/dL):</b> Tremor, palpitations, diaphoresis (cold sweats), anxiety, hunger, paresthesias <i>(Note: Beta-blockers mask tachycardia/tremor, leaving only sweating!)</i>.</li>\n<li class=\"l1\"><b>Neuroglycopenic Symptoms (&lt; 50 mg/dL):</b> Confusion, irritability, slurred speech, focal neurological deficits (<b>stroke mimic!</b>), seizures, coma.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Immediate Fingerstick Capillary Glucose</b> (do NOT delay treatment waiting for lab!).</li>\n<li class=\"l1\">In non-diabetic unexplained hypoglycemia: Draw blood <i>during the episode</i> for Plasma Glucose, <mark class=\"hl rx\"><b>Insulin</b></mark> , <b>C-peptide</b>, Proinsulin, Beta-hydroxybutyrate, and Sulfonylurea screen (exogenous insulin -&gt; high insulin + <b>low C-peptide</b>; insulinoma/sulfonylurea -&gt; high insulin + <b>high C-peptide</b>).</li>\n</ul><h3><b>5. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Acute ischemic stroke, Seizure disorder, Acute intoxication, Panic attack, Syncope, Septic encephalopathy.</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Conscious &amp; Able to Swallow (\"Rule of 15\"):</b> Give <b>15–20 g fast-acting carbohydrate</b> (e.g., 150 mL fruit juice, 3–4 glucose tablets, or 1 tablespoon honey/sugar in water); recheck glucose in <b>15 minutes</b>; repeat if still &lt; 70 mg/dL, then follow with a complex snack/meal.</li>\n<li class=\"l1\"><b>Unconscious / Seizing / Unable to Swallow:</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>IV Dextrose 50% (D50W):</b></mark> 25–50 mL IV push (or <b>D10W</b> 100–250 mL infusion).</li>\n<li class=\"l2\">If <b>NO IV access:</b> <mark class=\"hl rx\"><b>IM / Subcutaneous / Intranasal Glucagon 1 mg</b></mark> (note: ineffective in alcoholics/liver failure due to depleted glycogen!).</li>\n<li class=\"l2\"><i>If caused by Sulfonylurea (e.g., Glimepiride/Glibenclamide) or CKD:</i> <b>Admit for 24–48 hours</b> on <b>D10W infusion</b> due to prolonged delayed recurrence!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u37\">← Case 17</button><button class=\"nv\" data-u=\"u39\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u39\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Hypothyroidism</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypothyroidism\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>A clinical syndrome resulting from deficiency of thyroid hormones (<b>T4</b> [Thyroxine] and <b>T3</b> [Triiodothyronine]), leading to generalized slowing of metabolic processes.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Primary Hypothyroidism (&gt; 95% — High TSH, Low Free T4):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><b>Hashimoto’s Thyroiditis</b> (chronic autoimmune thyroiditis — #1 cause in iodine-sufficient areas; positive Anti-TPO antibodies).</li>\n<li class=\"l2\"><b>Iatrogenic:</b> Post-thyroidectomy, post-Radioactive Iodine (<b>RAI</b>) ablation for Graves’ disease, neck irradiation.</li>\n<li class=\"l2\"><b>Medications:</b> Amiodarone, Lithium, Interferon-alpha, Methimazole/PTU overtreatment.</li>\n<li class=\"l2\"><b>Iodine Deficiency</b> (still relevant in parts of the world/rural regions) or <b>Transient Thyroiditis</b> (Subacute De Quervain’s, Postpartum thyroiditis).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Secondary / Central Hypothyroidism (&lt; 5% — Low/Inappropriately Normal TSH, Low Free T4):</b></mark></span></p>\n<ul>\n<li class=\"l2\">Pituitary tumor/apoplexy, <b>Sheehan’s Syndrome</b> (postpartum pituitary necrosis after massive hemorrhage), hypothalamic disease.</li>\n</ul><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Fatigue, lethargy, weight gain (mild, mostly fluid), <b>cold intolerance</b>, constipation, dry coarse skin, hair loss (loss of lateral third of eyebrows — <b>Queen Anne’s sign</b>), periorbital puffiness, hoarse voice, <b>menorrhagia</b>, bradycardia, <b>delayed relaxation phase of deep tendon reflexes</b> (\"hung-up\" reflexes), carpal tunnel syndrome.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Myxedema Coma (Emergency):</b></mark> Hypothermia, bradycardia, hypoventilation (hypercapnia), hyponatremia, stupor/coma.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Initial Screening:</b> Serum <mark class=\"hl mech\"><b>TSH</b></mark> (Thyroid-Stimulating Hormone) + <mark class=\"hl mech\"><b>Free T4</b></mark> (diagnoses primary vs. central!).</li>\n<li class=\"l1\"><b>Etiologic:</b> <b>Anti-TPO</b> (Anti-Thyroid Peroxidase) antibodies (positive in ~90% of Hashimoto’s).</li>\n<li class=\"l1\"><b>Associated Labs:</b> Dyslipidemia (high <b>LDL</b>), hyponatremia, normocytic/macrocytic anemia, elevated <b>CK</b> (Creatine Kinase).</li>\n</ul><h3><b>5. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Major Depressive Disorder, <mark class=\"hl lab\"><b>IDA</b></mark> , Chronic Fatigue Syndrome, Nephrotic Syndrome, Heart Failure, Obesity/Sleep Apnea.</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Levothyroxine (L-T4):</b></mark></li>\n<li class=\"l2\"><i>Young, healthy adults:</i> Start full replacement dose <b>1.6 mcg/kg/day</b> orally.</li>\n<li class=\"l2\"><i>Elderly (&gt; 60 yrs) or </i><mark class=\"hl lab\"><i><b>CAD</b></i></mark><i> patients:</i> <b>\"Start Low, Go Slow\"</b> — start <b>12.5–25 mcg/day</b>, increase every 4–6 weeks (rapid replacement can precipitate angina/MI!).</li>\n<li class=\"l2\"><i>Administration Rule:</i> Take on an <b>empty stomach</b> with water <b>30–60 minutes before breakfast</b>, separated by 4 hours from <mark class=\"hl rx\"><b>Iron, Calcium, and PPIs</b></mark> !</li>\n<li class=\"l2\"><i>Monitoring:</i> Recheck <mark class=\"hl mech\"><b>TSH</b></mark> after <b>6–8 weeks</b> of any dose change (target TSH 0.5–2.5/4.0 mIU/L).</li>\n<li class=\"l2\"><i>Pregnancy:</i> Increase Levothyroxine dose by ~25–30% immediately upon positive pregnancy test (crucial for fetal neurodevelopment!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Myxedema Coma:</b></mark> ICU, <mark class=\"hl rx\"><b>IV Levothyroxine</b></mark> + <mark class=\"hl rx\"><b>IV Hydrocortisone</b></mark> (to cover potential concurrent adrenal insufficiency) + passive rewarming.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u38\">← Case 18</button><button class=\"nv\" data-u=\"u40\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u40\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Hyperthyroidism (THYROTOXICOSIS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hyperthyroidism+%28THYROTOXICOSIS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Hypermetabolic state caused by excess circulating thyroid hormones (<mark class=\"hl lab\"><b> Thyrotoxicosis</b></mark> ), most commonly from increased thyroid synthesis (<mark class=\"hl lab\"><b> Hyperthyroidism</b></mark> ).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>High Radioactive Iodine Uptake (True Hyperthyroidism):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><b>Graves’ Disease (~70–80%):</b> Autoimmune <b>TSI</b> (Thyroid-Stimulating Immunoglobulins / <b>TRAb</b>) activating TSH receptors.</li>\n<li class=\"l2\"><b>Toxic Multinodular Goiter (Plummer’s Disease):</b> Autonomous hyperfunctioning nodules (common in elderly).</li>\n<li class=\"l2\"><b>Toxic Adenoma:</b> Single autonomous hot nodule.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Low Radioactive Iodine Uptake (Destructive Release or Exogenous):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Subacute (De Quervain’s) Thyroiditis:</b> Painful tender goiter after viral URTI; high <mark class=\"hl mech\"><b>ESR</b></mark> .</li>\n<li class=\"l2\"><b>Silent / Postpartum Thyroiditis:</b> Painless.</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Exogenous Levothyroxine excess</b></mark> (Factitious thyrotoxicosis) or <mark class=\"hl rx\"><b>Amiodarone-induced thyroiditis</b></mark> .</li>\n</ul><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Weight loss despite <b>increased appetite</b>, <b>heat intolerance</b>, diaphoresis, palpitations, <mark class=\"hl lab\"><b>sinus tachycardia or Atrial Fibrillation</b></mark> (especially elderly!), fine resting hand tremor, anxiety/insomnia, hyperdefecation/diarrhea, oligomenorrhea, proximal muscle weakness, lid lag/stare.</li>\n<li class=\"l1\"><b>Graves’-Specific Signs:</b> Diffuse smooth goiter with audible <b>thyroid bruit</b>, <b>Graves’ Ophthalmopathy</b> (exophthalmos/proptosis, periorbital edema, diplopia), <b>Pretibial Myxedema</b> (raised waxy plaques on shins).</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> Suppressed <mark class=\"hl mech\"><b>TSH</b></mark> (&lt; 0.01 mIU/L) + Elevated <mark class=\"hl mech\"><b>Free T4</b></mark> and <mark class=\"hl mech\"><b>Free T3</b></mark> (if TSH low and Free T4 normal -&gt; check Free T3 for <i>T3-toxicosis</i>).</li>\n<li class=\"l1\"><b>Confirm Etiology:</b> <b>TRAb</b> (TSH Receptor Antibodies — positive in Graves’), <b>Thyroid Ultrasound with Doppler</b>, or <b>Radioactive Iodine Uptake (RAIU) Scan</b> (<i>Diffuse high uptake</i> = Graves’; <i>Patchy</i> = Toxic MNG; <i>Focal hot nodule</i> = Toxic adenoma; <i>Near-zero uptake</i> = Thyroiditis). <i>Avoid RAIU scan in pregnancy!</i></li>\n</ul><h3><b>5. Complications</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Atrial Fibrillation</b></mark> &amp; High-output heart failure, <mark class=\"hl lab\"><b>Osteoporosis</b></mark> , <mark class=\"hl lab\"><b>Thyroid Storm</b></mark> (life-threatening decompensation: fever &gt; 39°C, HR &gt; 140, delirium/agitation, vomiting/jaundice).</li>\n</ul><h3><b>6. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Immediate Symptom Control:</b> <b>Beta-blocker</b> — <mark class=\"hl rx\"><b>Propranolol</b></mark> (20–40 mg TID–QID; also blocks peripheral T4 -&gt; T3 conversion!) or Atenolol/Metoprolol.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Definitive Management Options (Graves’ / Toxic Goiter):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Antithyroid Drugs (ATDs):</b> <mark class=\"hl rx\"><b>Carbimazole / Methimazole</b></mark> (first-line, OD dosing; avoid Methimazole in <b>1st trimester pregnancy</b> -&gt; use <mark class=\"hl rx\"><b>PTU</b></mark> [Propylthiouracil] in 1st trimester due to aplasia cutis risk, then switch back to Methimazole in 2nd trimester!).</li>\n<li class=\"l1\"><i>Critical Warning to Patient:</i> Stop drug &amp; get urgent <mark class=\"hl mech\"><b>CBC</b></mark> if <b>sore throat + fever</b> develops (<b>Agranulocytosis</b>)! Also monitor for hepatotoxicity.</li>\n<li class=\"l2\"><b>Radioactive Iodine (I-131) Ablation:</b> Preferred in Toxic MNG/Adenoma or relapsed Graves’ (contraindicated in pregnancy/lactation and moderate-severe Graves’ ophthalmopathy).</li>\n<li class=\"l2\"><b>Thyroidectomy:</b> Preferred for very large compressive goiters, suspicious nodules, or severe ophthalmopathy.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Subacute Thyroiditis:</b></mark> Supportive (<mark class=\"hl rx\"><b> NSAIDs</b></mark> + Propranolol; Prednisone if severe pain) — <i>do NOT give ATDs!</i></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Thyroid Storm Protocol:</b></mark> <mark class=\"hl rx\"><b>Propranolol</b></mark> + <mark class=\"hl rx\"><b>PTU</b></mark> (blocks new synthesis AND T4-&gt;T3 conversion) + <b>Iodine (Lugol’s/SSKI)</b> <i>given 1 hour AFTER PTU</i> + <mark class=\"hl rx\"><b>IV Hydrocortisone</b></mark> + aggressive cooling.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u39\">← Case 19</button><button class=\"nv\" data-u=\"u41\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u41\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Iron Deficiency Anemia (IDA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Iron+Deficiency+Anemia+%28IDA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Microcytic, hypochromic anemia resulting from depletion of body iron stores, impairing hemoglobin synthesis. <b>Most common cause of anemia worldwide and in Egypt.</b></p><h3><b>2. Etiology (Separated by Age &amp; Sex — CRITICAL!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Chronic Blood Loss (#1 Cause in Adults):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Premenopausal Females:</i> <b>Menorrhagia</b> (heavy menstrual bleeding), pregnancy/lactation.</li>\n<li class=\"l2\"><i>Adult Males &amp; Postmenopausal Females:</i> <b>GI Blood Loss</b> (<mark class=\"hl rx\"><b> Peptic Ulcer, Gastritis, NSAIDs, Colorectal Carcinoma [until proven otherwise!], Angiodysplasia, Hookworm [</b></mark><i><b>Ancylostoma duodenale</b></i><mark class=\"hl rx\"><b>] in rural Egypt</b></mark> ).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Increased Iron Demand:</b> Infants/toddlers (excess cow’s milk), adolescent growth spurts, pregnancy.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Decreased Absorption:</b> <b>Celiac Disease</b>, <i>H. pylori</i> gastritis, autoimmune gastritis, post-gastrectomy/bariatric surgery, chronic <mark class=\"hl rx\"><b>PPI</b></mark> use.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Inadequate Dietary Intake:</b> Strict vegetarianism, malnutrition.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Fatigue, pallor (conjunctival, palmar creases), dyspnea on exertion, palpitations, headache.</li>\n<li class=\"l1\"><b>Specific Epithelial Signs:</b> <b>Koilonychia</b> (spoon-shaped nails), angular cheilitis/stomatitis, atrophic glossitis (smooth painful tongue), <b>Pica</b> (craving ice [pagophagia], clay/dirt), <b>Plummer-Vinson Syndrome</b> (IDA + esophageal webs + dysphagia).</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CBC + Peripheral Smear:</b></mark> Low <b>Hb</b>, Low <b>MCV</b> (Mean Corpuscular Volume &lt; 80 fL), Low <b>MCHC</b>, High <b>RDW</b> (Red Cell Distribution Width — anisocytosis), possible reactive <b>thrombocytosis</b>; smear shows microcytic hypochromic RBCs + pencil cells.</li>\n<li class=\"l1\"><b>Iron Studies (Confirmatory):</b></li>\n<li class=\"l2\"><b>Low Serum Ferritin (&lt; 15–30 ng/mL)</b> = <b>MOST SPECIFIC</b> test for iron deficiency! <i>(Caution: Ferritin is an acute-phase reactant and can be falsely normal/elevated in inflammation/infection!)</i></li>\n<li class=\"l2\">Low Serum Iron, <b>High TIBC</b> (Total Iron-Binding Capacity), Low Transferrin Saturation (&lt; 15–20%).</li>\n<li class=\"l1\"><b>Mandatory Etiologic Workup:</b> Stool analysis (parasites/occult blood); <b>Upper &amp; Lower GI Endoscopy</b> in ALL men and postmenopausal women with unexplained IDA!</li>\n</ul><h3><b>5. Differential Diagnosis (DDx — Microcytic Anemias: \"TAILS\")</b></h3><ul>\n<li class=\"l1\"><b>T</b>halassemia Trait (extremely common in Egypt! Normal/high RBC count, normal <b>RDW</b>, normal Ferritin, <b>Mentzer Index [MCV / RBC] &lt; 13</b> — confirm with <b>Hb Electrophoresis</b>!).</li>\n<li class=\"l1\"><b>A</b>nemia of Chronic Disease (<b>Low/normal TIBC</b>, high/normal Ferritin).</li>\n<li class=\"l1\"><b>I</b>ron Deficiency Anemia.</li>\n<li class=\"l1\"><b>L</b>ead Poisoning (basophilic stippling).</li>\n<li class=\"l1\"><b>S</b>ideroblastic Anemia (ringed sideroblasts).</li>\n</ul><h3><b>6. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Treat the Underlying Cause!</b> (e.g., gynecologic management, eradicate <i>H. pylori</i>, treat colon lesion).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Oral Iron Replacement (First-Line):</b> Ferrous sulfate/fumarate/gluconate (or Ferrous bisglycinate) providing ~<b>60–100 mg elemental iron once daily or on alternate days</b> (alternate-day dosing maximizes absorption by keeping <b>hepcidin</b> low and reduces GI side effects!).</span></p>\n<ul>\n<li class=\"l2\">Take on empty stomach with <b>Vitamin C</b> (orange juice); avoid tea, coffee, calcium, milk, and antacids for 2 hours! Warn patient of <b>black stools</b>.</li>\n<li class=\"l2\"><i>Duration:</i> Continue for <b>3–6 months AFTER Hb normalizes</b> to replenish Ferritin stores! (Expect Reticulocyte rise in 5–7 days and Hb rise ~1–2 g/dL every 3–4 weeks).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>IV Iron (Ferric Carboxymaltose / Iron Sucrose):</b> Indicated for oral intolerance, malabsorption (IBD/celiac), <mark class=\"hl lab\"><b>CKD</b></mark> , or severe late-pregnancy anemia.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u40\">← Case 20</button><button class=\"nv\" data-u=\"u42\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u42\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Vitamin B12 Deficiency &amp; Megaloblastic Anemia</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vitamin+B12+Deficiency+%26+Megaloblastic+Anemia\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Macrocytic anemia (<b>MCV &gt; 100 fL</b>) caused by impaired DNA synthesis due to <mark class=\"hl rx\"><b>Vitamin B12 (Cobalamin)</b></mark> or <b>Folate</b> deficiency.</p><h3><b>2. Etiology of Vitamin B12 Deficiency (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Malabsorption (Most Common):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Pernicious Anemia</b> (autoimmune destruction of gastric parietal cells / <b>Intrinsic Factor</b> antibodies).</li>\n<li class=\"l2\"><b>Terminal Ileum Disease/Resection</b> (Crohn’s disease, ileal resection — B12 is absorbed exclusively in the terminal ileum!).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Chronic Metformin or PPI use</b></mark> (very common in Egyptian diabetics!).</li>\n<li class=\"l2\"><i>H. pylori</i> gastritis, bariatric surgery, <i>Diphyllobothrium latum</i> (fish tapeworm).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Inadequate Intake:</b> Strict vegans (takes 3–5 years to deplete liver stores).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Anemia Signs:</b> Fatigue, pallor + <b>mild lemon-yellow jaundice</b> (from intramedullary hemolysis / ineffective erythropoiesis), beefy-red painful tongue (glossitis).</li>\n<li class=\"l1\"><b>Neurological Signs (UNIQUE TO B12 DEFICIENCY — Absent in Folate Deficiency!):</b></li>\n<li class=\"l2\"><b>Subacute Combined Degeneration of the Spinal Cord:</b> Dorsal columns (<b>loss of vibration &amp; proprioception</b>, sensory ataxia, positive <b>Romberg sign</b>) + Lateral corticospinal tracts (spastic paraparesis, hyperreflexia, Babinski +) + Peripheral neuropathy (\"glove-and-stocking\" paresthesia) + dementia/irritability.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CBC + Smear:</b></mark> High <b>MCV</b> (often &gt; 110–120 fL), pancytopenia in severe cases, <b>Hypersegmented Neutrophils</b> (≥ 5 lobes — pathognomonic!), macro-ovalocytes.</li>\n<li class=\"l1\"><b>Labs:</b> Low <mark class=\"hl rx\"><b>Serum Vitamin B12</b></mark> (&lt; 200 pg/mL), elevated <mark class=\"hl mech\"><b>LDH</b></mark> &amp; indirect bilirubin.</li>\n<li class=\"l1\"><b>Metabolites (If borderline B12 200–300 pg/mL):</b></li>\n<li class=\"l2\"><b>Both B12 &amp; Folate deficiency</b> elevate <b>Homocysteine</b>.</li>\n<li class=\"l2\"><b>ONLY B12 deficiency</b> elevates <b>MMA</b> (Methylmalonic Acid)!</li>\n<li class=\"l1\"><b>Pernicious Anemia:</b> Anti-Intrinsic Factor Antibodies (high specificity) + Anti-Parietal Cell Antibodies.</li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Vitamin B12 Replacement:</b></mark></li>\n<li class=\"l2\"><i>If Neurological Symptoms or Malabsorption (Pernicious/Ileal):</i> <b>IM Cyanocobalamin or Hydroxocobalamin 1,000 mcg</b> daily for 1 week -&gt; weekly for 4 weeks -&gt; <b>monthly lifelong</b>!</li>\n<li class=\"l2\"><i>Dietary / Metformin-induced (intact absorption):</i> High-dose oral Vitamin B12 (1,000–2,000 mcg/day).</li>\n<li class=\"l1\"><b>CRITICAL SAFETY RULE:</b> <mark class=\"hl rx\"><b>NEVER give Folate alone to a patient with suspected Megaloblastic Anemia without ruling out or treating Vitamin B12 deficiency! </b></mark>Folate corrects the anemia while allowing irreversible spinal cord demyelination to progress!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u41\">← Case 21</button><button class=\"nv\" data-u=\"u43\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u43\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Urinary Tract Infection (CYSTITIS &amp; ACUTE PYELONEPHRITIS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urinary+Tract+Infection+%28CYSTITIS+%26+ACUTE+PYELONEPHRITIS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><b>Uncomplicated Cystitis:</b> Lower <b>UTI</b> (bladder infection) in a non-pregnant, premenopausal female with normal urinary tract anatomy.</li>\n<li class=\"l1\"><b>Acute Pyelonephritis:</b> Upper <b>UTI</b> involving the renal parenchyma and pelvis (always considered complicated if pregnant, male, obstructed, or catheterized).</li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Community-Acquired Pathogens:</b> <i><b>Escherichia coli</b></i> (~75–85%), <i>Staphylococcus saprophyticus</i> (young sexually active females), <i>Klebsiella pneumoniae</i>, <i>Proteus mirabilis</i> (urease producer -&gt; alkaline urine &amp; struvite stones!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hospital / Catheter-Associated:</b> <i>Pseudomonas aeruginosa</i>, <i>Enterococcus</i>, <b>ESBL</b> (Extended-Spectrum Beta-Lactamase) producing <i>E. coli/Klebsiella</i>, <i>Candida</i>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Risk Factors:</b> Female anatomy, sexual intercourse, spermicides, urinary obstruction (stones, <mark class=\"hl lab\"><b>BPH</b></mark> ), urinary catheters, <b>DM</b>, pregnancy.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Cystitis:</b> Dysuria, urinary frequency, urgency, suprapubic discomfort, cloudy/foul-smelling urine — <b>NO fever, NO flank pain</b>.</li>\n<li class=\"l1\"><b>Acute Pyelonephritis:</b> High fever (&gt; 38.5°C), chills/rigors, <b>flank pain</b>, <b>CVA</b> (Costovertebral Angle) tenderness, nausea/vomiting (+/- cystitis symptoms).</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Uncomplicated Cystitis:</b> Urinalysis (positive <b>Leukocyte Esterase</b> [pyuria], positive <b>Nitrites</b> [Gram-negative bacteria]); urine culture not mandatory unless recurrent/atypical.</li>\n<li class=\"l1\"><b>Acute Pyelonephritis / Complicated UTI / Pregnancy / Males:</b> <b>Urine Analysis + Urine Culture &amp; Sensitivity</b> BEFORE starting antibiotics! Plus <mark class=\"hl mech\"><b>CBC</b></mark> , <mark class=\"hl mech\"><b>RFTs</b></mark> , Blood Cultures (if toxic/febrile), and <b>Renal Ultrasound</b> (MANDATORY if non-improving at 48–72 hrs or severe pain to rule out <b>obstructed infected kidney</b>!).</li>\n</ul><h3><b>5. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Urethritis (<i>Chlamydia/Gonorrhea</i>), Vaginitis (<i>Candida/Trichomonas</i>), Nephrolithiasis, Acute Appendicitis, <b>PID</b>, Prostatitis (in males: fever + perineal pain + boggy tender prostate!).</li>\n</ul><h3><b>6. Complications</b></h3><ul>\n<li class=\"l1\">Urosepsis/Septic shock, Renal abscess, Emphysematous pyelonephritis (gas in kidney in uncontrolled diabetics!), Preterm labor in pregnancy.</li>\n</ul><h3><b>7. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Uncomplicated Acute Cystitis (First-Line):</b></li>\n<li class=\"l2\"><b>Nitrofurantoin</b> 100 mg BID for 5 days <i>(safe in pregnancy except at term; avoid if eGFR &lt; 30 or pyelonephritis!)</i>.</li>\n<li class=\"l2\"><b>Fosfomycin</b> 3 g single oral sachet.</li>\n<li class=\"l2\"><b>TMP-SMX</b> (Trimethoprim-Sulfamethoxazole) DS BID for 3 days (if local resistance &lt; 20%).</li>\n<li class=\"l2\"><i>(Avoid Fluoroquinolones for simple cystitis due to side effects &amp; resistance!).</i></li>\n<li class=\"l1\"><b>Acute Pyelonephritis:</b></li>\n<li class=\"l2\"><i>Outpatient (mild, tolerating PO):</i> Ciprofloxacin 500 mg BID for 7 days or Levofloxacin 750 mg OD for 5 days (after single IV dose of Ceftriaxone 1 g if local resistance high).</li>\n<li class=\"l2\"><i>Inpatient (vomiting, sepsis, pregnancy, elderly):</i> <mark class=\"hl rx\"><b>IV Ceftriaxone 1–2 g/day</b></mark> (or Piperacillin-Tazobactam / Carbapenem if <b>ESBL</b> risk suspected) -&gt; de-escalate per culture for 10–14 days total.</li>\n<li class=\"l2\"><i>Asymptomatic Bacteriuria:</i> Treat <b>ONLY</b> in <mark class=\"hl lab\"><b>Pregnancy</b></mark> and <b>before invasive urologic procedures</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u42\">← Case 22</button><button class=\"nv\" data-u=\"u44\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u44\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Acute Kidney Injury (AKI)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Kidney+Injury+%28AKI%29\">🔍 Search on Google</a></header><h3><b>1. Definition (KDIGO Criteria — Any 1 of 3)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Rise in Serum Creatinine <b>≥ 0.3 mg/dL within 48 hours</b>, OR</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Rise in Serum Creatinine <b>≥ 1.5× baseline within 7 days</b>, OR</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\">Urine output <b>&lt; 0.5 mL/kg/hr for ≥ 6 hours</b>.</span></p><h3><b>2. Etiology (Separated by Anatomical Mechanism)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Prerenal AKI (~60–70% — Reduced Renal Perfusion, Intact Parenchyma):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><i>True Volume Depletion:</i> Hemorrhage, dehydration, diarrhea, vomiting, burns, excess diuretics.</li>\n<li class=\"l2\"><i>Reduced Effective Arterial Volume:</i> Heart failure, Cirrhosis (<b>Hepatorenal Syndrome</b>), Sepsis.</li>\n<li class=\"l2\"><i>Autoregulation Drugs:</i> <mark class=\"hl rx\"><b>NSAIDs</b></mark> (constrict afferent arteriole) + <mark class=\"hl rx\"><b>ACE-i / ARBs</b></mark> (dilate efferent arteriole).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Intrinsic (Renal) AKI (~25–40%):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><i>ATN (Acute Tubular Necrosis — #1 intrinsic):</i> Prolonged prerenal ischemia, sepsis, nephrotoxins (Aminoglycosides, Vancomycin, IV <b>Contrast</b>, Cisplatin, <b>Rhabdomyolysis</b> [myoglobin]).</li>\n<li class=\"l2\"><i>AIN (Acute Interstitial Nephritis):</i> Drug hypersensitivity (<mark class=\"hl rx\"><b> Beta-lactams, PPIs, NSAIDs, Rifampin</b></mark> ) -&gt; fever, rash, eosinophilia/eosinophiluria.</li>\n<li class=\"l2\"><i>Glomerulonephritis (RPGN):</i> <mark class=\"hl lab\"><b>SLE</b></mark> , <mark class=\"hl mech\"><b>ANCA</b></mark> vasculitis, PSGN -&gt; dysmorphic RBCs, <b>RBC casts</b>, hypertension.</li>\n<li class=\"l2\"><i>Vascular:</i> <mark class=\"hl lab\"><b>TTP/HUS</b></mark> , Malignant hypertension, Renal atheroemboli.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Postrenal AKI (~5–10% — Urinary Tract Obstruction; requires bilateral obstruction or single functioning kidney!):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl lab\"><b>BPH</b></mark> (Benign Prostatic Hyperplasia — #1 in elderly men!), Bilateral ureteric stones, Pelvic malignancy (cervical/bladder), Blocked Foley catheter.</li>\n</ul><h3><b>3. Diagnostic Differentiation (Prerenal vs. Intrinsic ATN)</b></h3><table class=\"t \"><tr class=\"hd\"><th></th><th></th><th></th></tr><tr><td><p><b>BUN : Creatinine Ratio</b></p></td><td><p><b>&gt; 20 : 1</b></p></td><td><p>10–15 : 1</p></td></tr><tr><td><p><b>Urine Sodium (UNa)</b></p></td><td><p><b>&lt; 20 mEq/L</b></p></td><td><p><b>&gt; 40 mEq/L</b></p></td></tr><tr><td><p><b>FENa</b> (Fractional Excretion of Na+)</p></td><td><p><b>&lt; 1%</b> <i>(unreliable if on diuretics -&gt; use FEUrea &lt; 35%)</i></p></td><td><p><b>&gt; 2%</b></p></td></tr><tr><td><p><b>Urine Osmolality</b></p></td><td><p><b>&gt; 500 mOsm/kg</b></p></td><td><p>&lt; 350 mOsm/kg</p></td></tr><tr><td><p><b>Urine Microscopy</b></p></td><td><p>Hyaline casts / Normal</p></td><td><p><b>\"Muddy brown\" granular casts</b></p></td></tr></table><h3><b>4. Mandatory Initial Workup</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>RFTs</b></mark> , Electrolytes (<b>K+</b>, <b>HCO3-</b>), <mark class=\"hl mech\"><b>CBC</b></mark> , <mark class=\"hl mech\"><b>Urinalysis + Microscopy</b></mark> , <mark class=\"hl mech\"><b>ECG</b></mark> (check hyperkalemia!), and <b>Renal Ultrasound</b> (rule out hydronephrosis/postrenal obstruction immediately!).</li>\n</ul><h3><b>5. Complications &amp; Emergency Dialysis Indications (\"AEIOU\")</b></h3><ul>\n<li class=\"l1\"><b>A</b>cidosis (severe refractory metabolic acidosis, pH &lt; 7.1)</li>\n<li class=\"l1\"><b>E</b>lectrolytes (refractory life-threatening <b>Hyperkalemia</b>)</li>\n<li class=\"l1\"><b>I</b>ntoxications (Methanol, Ethylene glycol, Lithium, Salicylates)</li>\n<li class=\"l1\"><b>O</b>verload (diuretic-refractory <b>Pulmonary Edema</b>)</li>\n<li class=\"l1\"><b>U</b>remia (Uremic <mark class=\"hl lab\"><b>Encephalopathy</b></mark> , <b>Pericarditis</b>, or Bleeding)</li>\n</ul><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Stop all nephrotoxins immediately</b> (NSAIDs, Aminoglycosides, ACE-i/ARBs temporarily, Metformin) and <b>adjust drug doses</b> for renal function!</li>\n<li class=\"l1\"><b>Prerenal:</b> Judicious IV isotonic crystalloids (monitor closely to avoid pulmonary edema).</li>\n<li class=\"l1\"><b>Postrenal:</b> Immediate bladder catheterization (for BPH/retention) or <mark class=\"hl rx\"><b>PCN / JJ stent</b></mark> (for upper tract obstruction).</li>\n<li class=\"l1\"><b>Intrinsic:</b> Supportive care, treat underlying GN/AIN (remove drug +/- steroids for AIN; immunosuppression for RPGN).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u43\">← Case 23</button><button class=\"nv\" data-u=\"u45\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u45\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Chronic Kidney Disease (CKD)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Kidney+Disease+%28CKD%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Kidney damage (e.g., albuminuria ≥ 30 mg/day, abnormal imaging/biopsy) OR <b>eGFR &lt; 60 mL/min/1.73 m²</b> persisting for <b>≥ 3 months</b>.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Diabetic Nephropathy</b> (#1 cause worldwide and in Egypt).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hypertensive Nephrosclerosis</b> (#2 cause).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Glomerulonephritis</b> (IgA nephropathy, Lupus nephritis, <b>FSGS</b>, HCV-associated MPGN).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Polycystic Kidney Disease (ADPKD)</b>, Chronic Pyelonephritis / Reflux Nephropathy, Chronic Analgesic Nephropathy (<mark class=\"hl rx\"><b> NSAIDs</b></mark> ), <b>Schistosomal</b> obstructive uropathy.</span></p><h3><b>3. Staging (By eGFR mL/min/1.73 m²)</b></h3><ul>\n<li class=\"l1\"><b>G1:</b> ≥ 90 (with kidney damage) | <b>G2:</b> 60–89 | <b>G3a:</b> 45–59 | <b>G3b:</b> 30–44 | <b>G4:</b> 15–29 | <b>G5:</b> &lt; 15 (<mark class=\"hl mech\"><b> ESRD</b></mark> / Kidney Failure).</li>\n</ul><h3><b>4. Clinical Picture &amp; Complications (Often Silent until Stage 4–5!)</b></h3><ul>\n<li class=\"l1\">Nocturia, fatigue, pruritus, anorexia, nausea, peripheral edema, uncontrolled hypertension, restless legs, bone pain.</li>\n<li class=\"l1\"><b>Core Complications:</b></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Anemia of CKD:</b></mark> Normocytic normochromic anemia due to decreased <b>EPO</b> (Erythropoietin) production.</li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>CKD-MBD</b></mark> (Mineral &amp; Bone Disorder / Renal Osteodystrophy): Phosphate retention -&gt; <b>Hyperphosphatemia</b> + low active Vitamin D (<b>1,25-[OH]2D</b>) -&gt; <b>Hypocalcemia</b> -&gt; <b>Secondary Hyperparathyroidism</b> (high <b>PTH</b>).</li>\n<li class=\"l2\"><b>Metabolic Acidosis</b>, <b>Hyperkalemia</b>, <b>Cardiovascular Disease</b> (#1 cause of death in CKD!).</li>\n</ul><h3><b>5. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>RFTs + eGFR</b></mark> , <b>UACR</b> (Urine Albumin-to-Creatinine Ratio), Urinalysis, Serum Electrolytes (K+, Ca++, PO4), <b>PTH</b>, <b>25-OH Vitamin D</b>, <mark class=\"hl mech\"><b>CBC + Iron Studies</b></mark> (Ferritin, TSAT).</li>\n<li class=\"l1\"><b>Renal Ultrasound:</b> Differentiates CKD (<b>bilateral small echogenic kidneys &lt; 9 cm</b> with loss of corticomedullary differentiation) from AKI (normal-sized kidneys)! <i>(Exception: Diabetic nephropathy, Amyloidosis, ADPKD, and HIV nephropathy can have normal/large kidneys despite CKD!)</i></li>\n</ul><h3><b>6. Treatment (Slow Progression + Manage Complications)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Slow Progression:</b></span></p>\n<ul>\n<li class=\"l2\"><b>BP Control</b> (&lt; 120–130/80 mmHg) using <mark class=\"hl rx\"><b>ACE-i or ARB</b></mark> (reduces intraglomerular pressure &amp; proteinuria — monitor Cr/K+ after 2 weeks).</li>\n<li class=\"l2\"><b>SGLT2 Inhibitor</b> (Dapagliflozin/Empagliflozin — reduces CKD progression &amp; CV death even in <i>non-diabetic</i> CKD down to eGFR 20!).</li>\n<li class=\"l2\"><b>Finerenone</b> (non-steroidal MRA in Diabetic CKD) + <mark class=\"hl rx\"><b>Statin</b></mark> for CV protection.</li>\n<li class=\"l2\">Strict avoidance of <mark class=\"hl rx\"><b>NSAIDs</b></mark> and unnecessary IV contrast.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Manage Complications:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Anemia:</i> Correct iron stores first (Target Ferritin &gt; 100–200, TSAT &gt; 20%), then <b>ESA</b> (Erythropoiesis-Stimulating Agents e.g., Epoetin alfa/Darbepoetin) targeting <b>Hb 10–11.5 g/dL</b> (do NOT normalize &gt; 13 -&gt; increases stroke/thrombosis!).</li>\n<li class=\"l2\"><i>CKD-MBD:</i> Dietary phosphate restriction + <b>Phosphate Binders</b> (Calcium acetate or Sevelamer with meals) + Vitamin D analogues (Calcitriol/Alfacalcidol).</li>\n<li class=\"l2\"><i>Acidosis:</i> Oral <b>Sodium Bicarbonate</b> if HCO3- &lt; 22 mEq/L.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Prepare for Renal Replacement Therapy (eGFR &lt; 15–20):</b> <b>AV Fistula</b> creation early, Hemodialysis, Peritoneal Dialysis, or <b>Kidney Transplantation</b> (best outcome).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u44\">← Case 24</button><button class=\"nv\" data-u=\"u46\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u46\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Nephrolithiasis (RENAL &amp; URETERIC STONES)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nephrolithiasis+%28RENAL+%26+URETERIC+STONES%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Formation of crystalline mineral calculi within the renal pelvis/calyces that may migrate into the ureter causing acute obstruction (<b>Renal Colic</b>).</p><h3><b>2. Stone Types &amp; Etiologies (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Calcium Oxalate / Phosphate (~75–80% — Radiopaque):</b> Hypercalciuria, hyperoxaluria (malabsorption/Crohn’s, high oxalate diet), hypocitraturia, low fluid intake (very common in hot Egyptian summers!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Uric Acid (~10% — Radiolucent on plain X-ray!):</b> Acidic urine (pH &lt; 5.5), Gout, metabolic syndrome/T2DM, tumor lysis.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Struvite / Magnesium Ammonium Phosphate (~5–10% — Radiopaque \"Staghorn\" Calculi):</b> Chronic UTI with <b>urease-producing bacteria</b> (<i>Proteus, Klebsiella</i>) -&gt; alkaline urine.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Cystine (~1% — Faintly Radiopaque):</b> Autosomal recessive defect in renal dibasic amino acid reabsorption (young patient, <b>hexagonal crystals</b>).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Sudden severe colicky flank pain</b> radiating to the <b>groin, testis, or labia</b>, coming in waves; patient is <b>restless and writhing in pain</b> (unlike peritonitis, where patient lies completely still!).</li>\n<li class=\"l1\">Nausea/vomiting, gross or microscopic <b>hematuria</b> (absent in ~10–15%).</li>\n<li class=\"l1\"><b>Distal Ureteric Stone:</b> Mimics cystitis (urinary frequency, urgency, dysuria).</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Urinalysis:</b></mark> RBCs, crystals, pH, rule out infection (pyuria/nitrites).</li>\n<li class=\"l1\"><b>Labs:</b> <mark class=\"hl mech\"><b>RFTs</b></mark> , Serum Ca++, Uric acid, <mark class=\"hl mech\"><b>CBC</b></mark> (if febrile).</li>\n<li class=\"l1\"><b>Imaging:</b></li>\n<li class=\"l2\"><b>Non-Contrast Helical CT Abdomen &amp; Pelvis (CT KUB):</b> <mark class=\"hl mech\"><b>Gold standard</b></mark> (detects &gt; 95% of stones including radiolucent uric acid stones, plus hydronephrosis).</li>\n<li class=\"l2\"><b>Abdominal Ultrasound:</b> First-line in <mark class=\"hl lab\"><b>Pregnancy</b></mark> and <b>Children</b> (avoids radiation).</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 5. Complications &amp; Emergency Red Flag</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>Infected Obstructed Kidney (Stone + Fever/Rigors):</b> <b>TRUE UROLOGICAL EMERGENCY!</b> High risk of fatal urosepsis -&gt; requires immediate IV antibiotics + <b>emergent decompression</b> (<b>JJ Stent</b> or <mark class=\"hl rx\"><b>PCN</b></mark> ) — do NOT attempt stone extraction during sepsis!</li>\n</ul></div></div><h3><b>6. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Acute Renal Colic Analgesia:</b> <mark class=\"hl rx\"><b>IV/IM NSAIDs</b></mark> (e.g., Ketorolac 30 mg or Diclofenac 75 mg — superior to opioids because they reduce ureteral smooth muscle prostaglandin spasm!) +/- IV Opioids if severe/renal impairment.</li>\n<li class=\"l1\"><b>Medical Expulsive Therapy (MET) for Uncomplicated Stones:</b></li>\n<li class=\"l2\">Stones <b>&lt; 5 mm</b>: ~80% pass spontaneously with hydration + analgesia.</li>\n<li class=\"l2\">Stones <b>5–10 mm</b> (especially distal ureter): <b>Tamsulosin 0.4 mg daily</b> (alpha-blocker relaxes distal ureter) for up to 4 weeks.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Urological Intervention (If &gt; 10 mm, refractory pain, AKI/solitary kidney, failed passage &gt; 4–6 wks):</b></mark> <b>ESWL</b> (Extracorporeal Shock Wave Lithotripsy), <b>Ureteroscopy (URS)</b> with laser lithotripsy, or <mark class=\"hl rx\"><b>PCNL</b></mark> (Percutaneous Nephrolithotomy for &gt; 2 cm / staghorn stones).</li>\n<li class=\"l1\"><b>Prevention:</b> Drink <b>&gt; 2.5–3 L water/day</b>, normal dietary calcium (do NOT overly restrict calcium!), limit sodium &amp; animal protein; <b>Thiazide</b> for hypercalciuria, <b>Potassium Citrate</b> for hypocitraturia/uric acid stones.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u45\">← Case 25</button><button class=\"nv\" data-u=\"u47\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u47\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Gout &amp; Hyperuricemia</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gout+%26+Hyperuricemia\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Inflammatory crystal arthropathy caused by deposition of <b>MSU</b> (Monosodium Urate) needle-shaped crystals in joints and soft tissues due to chronic hyperuricemia (&gt; 6.8 mg/dL).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Underexcretion of Uric Acid (~90% of cases):</b> Genetic predisposition, <mark class=\"hl lab\"><b>CKD</b></mark> , Drugs (<b>Thiazide &amp; Loop diuretics</b>, low-dose Aspirin, Cyclosporine), dehydration, metabolic syndrome.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Overproduction of Uric Acid (~10%):</b> High-purine diet (red meat, organ meats/liver, seafood), fructose-sweetened drinks, alcohol (especially beer), <b>Tumor Lysis Syndrome</b>, psoriasis, myeloproliferative disorders.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Acute Gouty Arthritis:</b></mark> Sudden nocturnal onset of <b>excruciating, hot, red, swollen monoarthritis</b> peaking within 12–24 hours (patient cannot tolerate even a bedsheet touching the toe!).</li>\n<li class=\"l2\"><b>Podagra</b> (1st <b>MTP</b> [Metatarsophalangeal] joint) is the classic site (&gt; 50%), followed by midfoot, ankle, and knee.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Chronic Tophaceous Gout:</b></mark> Painless firm subcutaneous nodules (<b>Tophi</b>) on ear helix, olecranon bursa, Achilles tendon, and finger joints + \"rat-bite\" punched-out bone erosions on X-ray.</li>\n</ul><h3><b>4. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Gold Standard:</b> <mark class=\"hl rx\"><b>Synovial Fluid Aspiration (Arthrocentesis)</b></mark> -&gt; Polarized light microscopy shows <b>needle-shaped, negatively birefringent intracellular crystals </b>(yellow when parallel to polarizer) + Gram stain/culture to <mark class=\"hl lab\"><b>RULE OUT Septic Arthritis</b></mark> !</li>\n<li class=\"l1\"><b>Serum Uric Acid:</b> Useful baseline, <i>but may be normal or even LOW during an acute gout attack!</i> (Check 2+ weeks after flare resolves).</li>\n</ul><h3><b>5. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Septic Arthritis</b></mark> (MUST ALWAYS RULE OUT in an acute hot swollen monoarthritis!), <mark class=\"hl lab\"><b>Pseudogout / CPPD</b></mark> (positively birefringent rhomboid crystals), Cellulitis, Reactive arthritis, Trauma.</li>\n</ul><h3><b>6. Treatment (Crucial Separation: Acute Flare vs. Chronic Prevention!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Acute Gout Flare (Start within 24 hours):</b></mark></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>NSAIDs</b></mark> (Naproxen 500 mg BID, Indomethacin 50 mg TID, or Etoricoxib) — avoid in CKD/PUD/CHF.</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Colchicine</b></mark> (1.2 mg stat, then 0.6 mg 1 hour later [total 1.8 mg Day 1], then 0.6 mg OD/BID) — most effective within 24–36 hrs of onset; reduce dose in CKD!</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Corticosteroids</b></mark> (Oral Prednisone 30–40 mg/day for 5 days, IM Triamcinolone, or Intra-articular injection after ruling out septic arthritis) — safest in <mark class=\"hl lab\"><b>CKD</b></mark> or elderly!</li>\n<li class=\"l2\"><b>GOLDEN RULE:</b> <mark class=\"hl rx\"><b>NEVER start or stop Allopurinol/Febuxostat DURING an acute gout flare</b></mark> (sudden uric acid shifts worsen/prolong the flare!).</li>\n<li class=\"l1\"><b>Chronic Urate-Lowering Therapy (ULT):</b></li>\n<li class=\"l2\"><i>Indications:</i> ≥ 2 flares/year, <b>Tophi</b>, Uric acid kidney stones, CKD stage ≥ 3, or radiographic erosions.</li>\n<li class=\"l2\"><i>Agents:</i> <mark class=\"hl rx\"><b>Allopurinol</b></mark> (start low 100 mg/day, titrate up to target <b>Serum Uric Acid &lt; 6.0 mg/dL</b>; check HLA-B*5801 if East Asian; start 50 mg in CKD) OR <mark class=\"hl rx\"><b>Febuxostat</b></mark> (40–80 mg/day — caution in severe CV disease!).</li>\n<li class=\"l2\"><i>Mandatory Flare Prophylaxis:</i> Give low-dose <mark class=\"hl rx\"><b>Colchicine 0.5–0.6 mg/day</b></mark> (or low-dose NSAID) for the first <b>3–6 months</b> when initiating Allopurinol/Febuxostat!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u46\">← Case 26</button><button class=\"nv\" data-u=\"u48\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u48\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Rheumatoid Arthritis (RA) &amp; Osteoarthritis (OA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Rheumatoid+Arthritis+%28RA%29+%26+Osteoarthritis+%28OA%29\">🔍 Search on Google</a></header><h4><b>Comparison Table: The Classic Clinical Distinction</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><mark class=\"hl lab\"><b>Rheumatoid Arthritis (RA)</b></mark></p></th><th><p><mark class=\"hl lab\"><b>Osteoarthritis (OA)</b></mark></p></th></tr><tr><td><p><b>Pathophysiology</b></p></td><td><p>Chronic autoimmune <b>synovitis</b> (pannus formation eroding cartilage &amp; bone)</p></td><td><p>Degenerative <b>\"wear-and-tear\"</b> cartilage breakdown + osteophytes</p></td></tr><tr><td><p><b>Typical Patient</b></p></td><td><p>Young/middle-aged <b>Female (30–50 yrs)</b></p></td><td><p><b>Elderly (&gt; 55 yrs)</b>, obese, or prior joint trauma</p></td></tr><tr><td><p><b>Joint Pattern</b></p></td><td><p><b>Symmetric polyarthritis</b> of small joints (<b>MCP</b>, <b>PIP</b>, wrists, MTP); <b>SPARES DIP joints!</b></p></td><td><p><b>Asymmetric</b>, weight-bearing joints (<b>Knees, Hips</b>, Lumbar/Cervical spine) + <b>DIP</b> (<b>Heberden’s</b>) &amp; <b>PIP </b>(<b>Bouchard’s</b>) + 1st <b>CMC</b></p></td></tr><tr><td><p><b>Stiffness &amp; Pain</b></p></td><td><p>Morning stiffness <b>&gt; 1 hour</b>; improves with activity</p></td><td><p>Morning stiffness <b>&lt; 30 minutes</b>; <b>worsens with use / end of day</b></p></td></tr><tr><td><p><b>Systemic / Extra-Articular</b></p></td><td><p>Fatigue, fever, <b>Rheumatoid nodules</b>, <b>ILD</b> (Interstitial Lung Disease), <b>Atlantoaxial subluxation</b> (check C-spine before intubation!), Felty syndrome, Vasculitis</p></td><td><p><b>NO systemic symptoms</b></p></td></tr><tr><td><p><b>Labs</b></p></td><td><p>Elevated <mark class=\"hl mech\"><b>ESR/CRP</b></mark> , <b>Anti-CCP</b> (most specific, 95%!), <b>RF </b>(Rheumatoid Factor)</p></td><td><p><mark class=\"hl rx\"><b>Normal</b></mark> ESR, CRP, RF, Anti-CCP</p></td></tr><tr><td><p><b>X-Ray Findings</b></p></td><td><p>Periarticular osteopenia, <b>marginal bone erosions</b>, uniform joint space narrowing</p></td><td><p><b>Subchondral sclerosis</b>, <b>osteophytes</b> (bone spurs), <b>subchondral cysts</b>, asymmetric joint space narrowing</p></td></tr></table><h4><b>Treatment Overview</b></h4><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Rheumatoid Arthritis (Treat Early to Prevent Deformity!):</b></mark></li>\n<li class=\"l2\"><i>Bridge Therapy (Symptom relief):</i> Short-term low-dose <mark class=\"hl rx\"><b>Prednisone</b></mark> + <mark class=\"hl rx\"><b>NSAIDs</b></mark> .</li>\n<li class=\"l2\"><i>First-Line </i><i><b>DMARD</b></i><i> (Disease-Modifying Antirheumatic Drug):</i> <mark class=\"hl rx\"><b>Methotrexate</b></mark> (10–25 mg <b>ONCE WEEKLY</b> + <b>Folic Acid</b> 5 mg/week to prevent toxicity; check CBC, LFTs, CXR, HBV/HCV/TB before starting; <b>strictly teratogenic</b>!).</li>\n<li class=\"l2\"><i>Alternatives / Add-ons:</i> Leflunomide, Sulfasalazine, Hydroxychloroquine (requires regular eye exams).</li>\n<li class=\"l2\"><i>Refractory / Severe:</i> <b>Biologics</b> (Anti-TNF: Adalimumab, Etanercept, Infliximab — <b>MUST screen for latent TB &amp; HBV first!</b>) or <b>JAK inhibitors</b> (Tofacitinib).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Osteoarthritis:</b></mark></li>\n<li class=\"l2\"><i>Non-Pharmacologic (First-Line):</i> Weight loss, quadriceps strengthening exercises, physical therapy, knee brace/cane.</li>\n<li class=\"l2\"><i>Pharmacologic:</i> Topical <mark class=\"hl rx\"><b>NSAIDs</b></mark> (Diclofenac gel — safest first-line!), oral <b>Acetaminophen</b> or short-term oral <mark class=\"hl rx\"><b>NSAIDs</b></mark> (+ PPI if GI risk), <b>Duloxetine</b> (for chronic OA knee pain), Intra-articular <mark class=\"hl rx\"><b>Corticosteroid</b></mark> injections (temporary relief for acute flares).</li>\n<li class=\"l2\"><i>End-Stage:</i> Total Joint Arthroplasty (Knee/Hip replacement).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u47\">← Case 27</button><button class=\"nv\" data-u=\"u49\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u49\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Enteric (TYPHOID) Fever &amp; Brucellosis (EGYPTIAN FEBRILE CLASSICS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Enteric+%28TYPHOID%29+Fever+%26+Brucellosis+%28EGYPTIAN+FEBRILE+CLASSICS%29\">🔍 Search on Google</a></header><p class=\"muted\"><i>(Two of the most frequently encountered—and frequently over/misdiagnosed—causes of prolonged fever in Egypt!)</i></p><h3><b>A. Enteric (Typhoid) Fever</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <i><b>Salmonella enterica</b></i><b> serotype Typhi</b> (or Paratyphi); fecal-oral transmission via contaminated food/water.</li>\n<li class=\"l1\"><b>Clinical Picture (Step-Ladder Fever):</b></li>\n<li class=\"l2\"><i>Week 1:</i> Gradually rising fever, headache, malaise, <b>relative bradycardia</b> (<b>Faget’s sign</b> — high fever with unexpectedly slow pulse), constipation (or \"pea-soup\" diarrhea).</li>\n<li class=\"l2\"><i>Week 2:</i> High sustained fever (39–40°C), abdominal pain, <b>hepatosplenomegaly</b>, faint salmon-colored <b>Rose Spots</b> on trunk.</li>\n<li class=\"l2\"><i>Week 3 (Complications):</i> <b>Intestinal hemorrhage</b> or <b>Ileal perforation</b> (Peyer’s patches necrosis!), typhoid encephalopathy.</li>\n<li class=\"l1\"><b>Investigations:</b></li>\n<li class=\"l2\"><b>Blood Culture</b> (Gold standard in Week 1 — ~60–80% sensitive); <b>Bone Marrow Culture</b> (most sensitive even after antibiotics!). Stool/Urine cultures positive in Weeks 2–3.</li>\n<li class=\"l2\"><mark class=\"hl mech\"><b>CBC:</b></mark> Normal/low WBC (<b>Leukopenia</b> with relative lymphocytosis and eosinopenia!).</li>\n<li class=\"l2\"><i>Warning about </i><i><b>Widal Test</b></i><i>:</i> <b>Notoriously unreliable in endemic areas like Egypt</b> (high false-positives from past exposure/cross-reactivity); never diagnose typhoid on Widal alone!</li>\n<li class=\"l1\"><b>Treatment:</b> Due to widespread multidrug/fluoroquinolone resistance, empirical first-line is <mark class=\"hl rx\"><b>IV Ceftriaxone 2 g/day</b></mark> (for hospitalized/severe) or <mark class=\"hl rx\"><b>Oral Azithromycin</b></mark> 1 g Day 1 then 500 mg/day for 7 days (uncomplicated).</li>\n</ul><h3><b>B. Brucellosis (Malta / Mediterranean Fever)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <i><b>Brucella melitensis</b></i> (#1 in Egypt — transmitted via <b>unpasteurized milk/fresh cheese [Karish/soft cheese]</b> or direct contact with infected cattle/sheep/goats).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Undulating/night-time fever, <b>profuse drenching foul-smelling sweats</b>, severe <b>arthralgia / sacroiliitis / vertebral spondylodiscitis (low back pain)</b>, malaise, hepatosplenomegaly, lymphadenopathy.</li>\n<li class=\"l1\"><b>Investigations:</b></li>\n<li class=\"l2\"><b>Blood Culture</b> (alert lab to hold for 2–4 weeks; gold standard) or Bone Marrow Culture.</li>\n<li class=\"l2\"><b>Serology:</b> <b>Standard Tube Agglutination Test (SAT)</b> — titer <b>≥ 1:160</b> (or 4-fold rise) is diagnostic in symptomatic patients (Rose Bengal is a rapid screening test).</li>\n<li class=\"l1\"><b>Treatment (Requires Combination Therapy ≥ 6 Weeks to Prevent Relapse!):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Doxycycline 100 mg BID for 6 weeks PLUS Rifampin 600–900 mg OD for 6 weeks</b></mark> (all-oral regimen), OR <mark class=\"hl rx\"><b>Doxycycline (6 weeks) PLUS Gentamicin (7 days) / Streptomycin (14–21 days)</b></mark> (gold standard, especially in spondylitis!).</li>\n<li class=\"l2\"><i>In Pregnancy / Children &lt; 8 yrs:</i> <b>TMP-SMX + Rifampin</b> for 6 weeks.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u48\">← Case 28</button><button class=\"nv\" data-u=\"u50\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u50\" hidden style=\"--c:#b7791f\"><button class=\"back\" data-p=\"3\">← Internal Medicine</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Deep Vein Thrombosis (DVT) &amp; Critical Electrolyte Emergencies</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Deep+Vein+Thrombosis+%28DVT%29+%26+Critical+Electrolyte+Emergencies\">🔍 Search on Google</a></header><h4><mark class=\"hl lab\"><b>Part A: Deep Vein Thrombosis (DVT)</b></mark></h4><ul>\n<li class=\"l1\"><b>Definition:</b> Thrombus formation in a deep vein (most commonly lower extremity: popliteal/femoral/iliac veins).</li>\n<li class=\"l1\"><b>Etiology (Separated — Virchow’s Triad):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Venous Stasis:</i> Prolonged immobility, surgery, long-haul travel, paralysis, heart failure, pregnancy.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Endothelial Injury:</i> Trauma, orthopedic surgery (hip/knee replacement), indwelling central venous catheters.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i>Hypercoagulability:</i> Active <b>Malignancy</b>, Pregnancy/Estrogen (<b>OCPs</b>), <mark class=\"hl lab\"><b>APS</b></mark> (Antiphospholipid Syndrome), Factor V Leiden, Nephrotic syndrome.</span></p>\n<ul>\n<li class=\"l1\"><b>Clinical Picture:</b> Unilateral calf/thigh swelling (&gt; 3 cm difference vs. other leg), warmth, erythema, deep aching pain, tenderness along deep venous system, dilated superficial collateral veins.</li>\n<li class=\"l1\"><b>Diagnosis:</b></li>\n<li class=\"l2\">Apply <b>Wells Score</b> for DVT probability:</li>\n<li class=\"l2\"><i>Low probability:</i> Check <b>D-Dimer</b> (high negative predictive value — if negative, rules out DVT!).</li>\n<li class=\"l2\"><i>Moderate/High probability (or positive D-Dimer):</i> <b>Venous Compression Duplex Ultrasound</b> (non-compressible vein = diagnostic!).</li>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Treatment (Anticoagulation to prevent fatal PE [Pulmonary Embolism]!):</b></mark></li>\n<li class=\"l2\"><b>DOACs (First-Line):</b> <mark class=\"hl rx\"><b>Rivaroxaban</b></mark> (15 mg BID × 21 days, then 20 mg OD) or <mark class=\"hl rx\"><b>Apixaban</b></mark> (10 mg BID × 7 days, then 5 mg BID) — NO initial heparin bridge needed!</li>\n<li class=\"l2\"><b>LMWH</b> (Enoxaparin 1 mg/kg SC q12h) bridged to <mark class=\"hl rx\"><b>Warfarin</b></mark> (target <mark class=\"hl mech\"><b>INR 2.0–3.0</b></mark> ) — preferred in <mark class=\"hl lab\"><b>severe CKD (CrCl &lt; 30)</b></mark> , <mark class=\"hl lab\"><b>APS</b></mark> (Warfarin mandatory!), or <mark class=\"hl lab\"><b>Pregnancy</b></mark> (LMWH ONLY — Warfarin &amp; DOACs are contraindicated!).</li>\n<li class=\"l2\"><i>Duration:</i> <b>3 months</b> if provoked by reversible factor; <b>≥ 3–6 months / Extended</b> if unprovoked or active cancer.</li>\n</ul><h4><b>Part B: Critical Electrolyte Emergencies (Quick ER Mastery)</b></h4><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Life-Threatening Hyperkalemia (K+ &gt; 5.5–6.5 mEq/L):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Causes (Separated):</i> <mark class=\"hl lab\"><b>AKI/CKD</b></mark> , Drugs (<mark class=\"hl rx\"><b> ACE-i, ARBs, Spironolactone, NSAIDs, Trimethoprim</b></mark> ), Tissue lysis (Rhabdomyolysis, Tumor lysis), Insulin deficiency (DKA).</li>\n<li class=\"l2\"><i>ECG Progression:</i> <b>Peaked T waves</b> -&gt; <b>PR prolongation / flattened P waves</b> -&gt; <b>Widened QRS</b> -&gt; <b>Sine wave</b> -&gt; <b>VF / Asystole</b>!</li>\n<li class=\"l2\"><i>Emergency 3-Step Protocol (</i><i><b>\"C BIG K\"</b></i><i>):</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Stabilize Myocardium (Immediate):</b> <mark class=\"hl rx\"><b>IV Calcium Gluconate 10%</b></mark> (10 mL over 2–5 min; acts in 1–3 min, does NOT lower K+!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Shift K+ Intracellularly (Minutes):</b> <mark class=\"hl rx\"><b>Regular Insulin 10 U IV + 50 mL D50W</b></mark> (25 g glucose) + Nebulized <mark class=\"hl rx\"><b>Salbutamol</b></mark> (10–20 mg) +/- IV Sodium Bicarbonate (if acidotic).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Remove K+ from Body (Hours):</b> <mark class=\"hl rx\"><b>IV Furosemide</b></mark> (if making urine), Potassium binders (<b>Sodium Zirconium Cyclosilicate / Patiromer</b>), or <mark class=\"hl rx\"><b>Emergent Hemodialysis</b></mark> !</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Severe Symptomatic Hyponatremia (Na+ &lt; 120–125 mEq/L + Seizures / Coma):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Emergency Treatment:</i> <b>3% Hypertonic Saline</b> 100–150 mL IV bolus over 10–20 minutes (raises Na+ quickly by 4–6 mEq/L to stop brain herniation).</li>\n<li class=\"l2\"><i>GOLDEN SAFETY RULE:</i> Never raise serum Na+ by <b>more than 6–8 mEq/L in 24 hours</b> (risk of fatal <mark class=\"hl dx\"><b>Osmotic Demyelination Syndrome [ODS]</b></mark> / Locked-in syndrome)!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 3B —</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u49\">← Case 29</button></nav></article>"});
